import { Component, lazy, Suspense, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Link } from 'react-router-dom';
import { Activity, ArrowDownRight, ArrowRight, ArrowUpRight, Award, Bell, BookOpen, BookOpenCheck, BriefcaseBusiness, Building2, Check, CheckCircle2, ChevronRight, CircleHelp, ClipboardCheck, Clock3, Code2, FileText, Filter, GraduationCap, Layers3, MessageSquareWarning, Plus, Search, ShieldCheck, Sparkles, Target, TrendingUp, UsersRound, X } from 'lucide-react';
import api, { dataOf, errorMessage } from '../api/client';
import { useAuth } from '../app/AuthContext';
import { themeOptions } from '../app/ThemeContext';
import { matchesSearch } from '../utils/search';
import { Badge, EmptyState, ErrorNotice, Field, FormInput, FormSelect, Loading, Modal, PageMotion, ProgressBar, SectionHeading, StatCard } from '../components/Common';
import AdminQuestionManager from '../components/AdminQuestionManager';
const SkillPage = lazy(() => import('./SkillPage'));
const AssessmentRunner = lazy(() => import('./SkillPage').then((module) => ({ default: module.AssessmentRunner })));
const CodingRoundRunner = lazy(() => import('./SkillPage').then((module) => ({ default: module.CodingRoundRunner })));

class SkillPageBoundary extends Component {
  state = { hasError: false, error: null };

  static getDerivedStateFromError(error) { return { hasError: true, error }; }

  componentDidCatch(error) { console.error('Skill learning page could not render:', error); }

  componentDidUpdate(previousProps) {
    if (previousProps.skillId !== this.props.skillId && this.state.hasError) this.setState({ hasError: false, error: null });
  }

  render() {
    if (this.state.hasError) {
      return <PageMotion className="page-content"><ErrorNotice message={`The learning page could not display this content: ${this.state.error?.message || 'Unknown client rendering error'}`} onRetry={() => this.setState({ hasError: false, error: null })} /><details className="render-error-details"><summary>Show technical details</summary><pre>{this.state.error?.stack || String(this.state.error || 'No error details captured.')}</pre></details></PageMotion>;
    }
    return this.props.children;
  }
}

function useApiData(path) {
  const [data, setData] = useState(null); const [loading, setLoading] = useState(true); const [error, setError] = useState('');
  const requestSequence = useRef(0);
  const load = useCallback(async () => {
    if (!path) return;
    const requestId = ++requestSequence.current;
    setLoading(true); setError('');
    try { const response = await api.get(path); if (requestId === requestSequence.current) setData(dataOf(response)); }
    catch (reason) { if (requestId === requestSequence.current) setError(errorMessage(reason)); }
    finally { if (requestId === requestSequence.current) setLoading(false); }
  }, [path]);
  useEffect(() => { load(); }, [load]);
  return { data, loading, error, reload: load, setData };
}

const greeting = () => {
  const hour = new Date().getHours();
  return hour < 12 ? 'Good morning' : hour < 18 ? 'Good afternoon' : 'Good evening';
};
const initials = (name = '') => name.split(/\s+/).slice(0, 2).map((part) => part[0]).join('').toUpperCase();
const statusTone = (status) => ({ known: 'green', completed: 'green', 'in-progress': 'amber', missing: 'rose', offered: 'blue', accepted: 'green', rejected: 'rose', pending: 'amber', approved: 'green', resolved: 'green', 'in-review': 'blue' }[status] || 'neutral');
const statusLabel = (status) => ({ 'in-progress': 'In progress', 'rejected-final': 'Not selected', offered: 'Invitation', 'next-round': 'Next round' }[status] || (status || '').replaceAll('-', ' '));
const auditLabel = (row) => row.targetType === 'Complaint' ? 'Complaint update' : statusLabel(row.action);

export default function PortalPages({ role, section, skillId, user, onUserUpdated, onNavigate }) {
  if (skillId && role === 'student') return <SkillPageBoundary skillId={skillId}><Suspense fallback={<Loading label="Opening the learning workspace…" />}><SkillPage skillId={skillId} onNavigate={onNavigate} /></Suspense></SkillPageBoundary>;
  if (section === 'dashboard') return <Dashboard role={role} user={user} />;
  if (role === 'student' && section === 'skills') return <SkillCatalog user={user} />;
  if (role === 'student' && section === 'roadmap') return <Roadmap />;
  if (role === 'student' && section === 'learning') return <LearningHome />;
  if (section === 'opportunities') return role === 'student' ? <StudentOpportunities /> : <CompanyOpportunities />;
  if (section === 'candidates' && role === 'company') return <CandidateDiscovery />;
  if (section === 'recruitment') return <Recruitment role={role} />;
  if (section === 'results') return <AssessmentResults />;
  if (section === 'notifications') return <NotificationInbox />;
  if (section === 'complaints') return <Complaints role={role} />;
  if (section === 'profile') return <Profile user={user} onUserUpdated={onUserUpdated} />;
  if (role === 'admin' && section === 'approvals') return <AdminApprovals />;
  if (role === 'admin' && section === 'users') return <AdminUsers />;
  if (role === 'admin' && section === 'domains') return <AdminDomains />;
  if (role === 'admin' && section === 'readiness') return <AdminReadinessSettings />;
  if (role === 'admin' && section === 'skills') return <AdminSkills />;
  if (role === 'admin' && section === 'learning') return <AdminLearning />;
  if (role === 'admin' && ['practice', 'coding', 'tests'].includes(section)) return <AdminQuestionManager kind={section} />;
  if (role === 'admin' && section === 'activity') return <AdminActivity />;
  return <PageMotion className="page-content"><EmptyState icon={CircleHelp} title="This page is ready for your next step" description="Choose a section from the sidebar to continue." /></PageMotion>;
}

function Dashboard({ role, user }) {
  const endpoint = role === 'student' ? '/student/dashboard' : role === 'company' ? '/company/dashboard' : '/admin/dashboard';
  const { data, loading, error, reload } = useApiData(endpoint);
  if (loading) return <PageFrame><Loading /></PageFrame>;
  if (error) return <PageFrame><ErrorNotice message={error} onRetry={reload} /></PageFrame>;
  if (role === 'student') return <StudentDashboard data={data} user={user} />;
  if (role === 'company') return <CompanyDashboard data={data} user={user} />;
  return <AdminDashboard data={data} />;
}

function PageFrame({ children, className = '' }) { return <PageMotion className={'page-content ' + className}>{children}</PageMotion>; }

function StudentDashboard({ data, user }) {
  const gap = data.gap; const stats = data.stats || {}; const skills = gap?.skills || [];
  const mastered = skills.filter(({ status }) => ['known', 'completed'].includes(status));
  const focus = skills.filter(({ status }) => status === 'in-progress');
  const missing = skills.filter(({ status }) => status === 'missing');
  const activityDays = Array.from({ length: 7 }, (_item, index) => {
    const day = new Date(); day.setDate(day.getDate() - (6 - index));
    return { day: new Intl.DateTimeFormat('en-IN', { weekday: 'short' }).format(day), learn: Math.max(0, (data.activity || []).filter((item) => new Date(item.createdAt).toDateString() === day.toDateString()).length) };
  });
  const peakActivity = Math.max(1, ...activityDays.map(({ learn }) => learn));
  const skillStatusData = [
    { label: 'Established', value: mastered.length, color: 'var(--accent)' },
    { label: 'In progress', value: focus.length, color: '#d2a34d' },
    { label: 'To explore', value: missing.length, color: '#aab7bd' },
  ];
  const skillTotal = skillStatusData.reduce((total, item) => total + item.value, 0) || 1;
  const skillChartStops = skillStatusData.reduce((result, item) => {
    const end = result.end + (item.value / skillTotal) * 100;
    result.stops.push(`${item.color} ${result.end}% ${end}%`);
    result.end = end;
    return result;
  }, { end: 0, stops: [] }).stops.join(', ');
  return <PageFrame>
    <div className="dashboard-welcome"><div><div className="eyebrow">YOUR CAREER JOURNEY</div><h1>{greeting()}, {user.fullName?.split(' ')[0] || 'there'} <span className="wave">✦</span></h1><p>{gap?.skills?.length ? `You’re building toward ${user.careerDomain?.name || 'your next role'}. Keep your momentum.` : 'Choose your career direction to get a skill plan built around your goals.'}</p></div><div className="welcome-actions"><Link className="button button-primary" to="/student/roadmap">View my roadmap<ArrowRight size={16} /></Link></div></div>
    <div className="student-overview-grid">
      <article className="readiness-card"><div className="readiness-card-head"><div><div className="eyebrow">CAREER READINESS</div><h2>Your progress, in context</h2></div><div className="readiness-icon"><Target size={18} /></div></div><div className="readiness-main"><div className="readiness-circle" style={{ '--value': `${gap?.careerReadiness || 0}%` }}><div><strong>{gap?.careerReadiness ?? 0}<small>%</small></strong><span>READY</span></div></div><div className="readiness-copy"><strong>{gap?.skillCompletionPercentage >= 70 ? 'You’re building a strong base.' : 'Your next skills are clear.'}</strong><p>{gap?.readinessCounts?.verified || 0} verified · {gap?.readinessCounts?.completed || 0} completed · {gap?.readinessCounts?.['in-progress'] || 0} in progress</p><div className="readiness-meta"><span><i className="legend-dot dot-strong" />Verified or completed</span><span><i className="legend-dot dot-progress" />In progress</span><span><i className="legend-dot dot-gap" />To explore</span></div></div></div><div className="readiness-footer"><span>Skill gap</span><strong>{gap?.skillGapPercentage ?? 100}%</strong><span>Weighted skill confidence, freshness, and relative demand across current YESGAP opportunities.</span></div></article>
      <article className="streak-card"><div className="streak-card-top"><span className="streak-symbol">✦</span><span className="streak-badge">YOUR MOMENTUM</span></div><strong className="streak-number">{stats.currentStreak}<small> days</small></strong><h3>Keep your rhythm</h3><p>Small, steady sessions can turn into lasting progress.</p><div className="streak-week">{Array.from({ length: 7 }, (_item, index) => { const active = index >= 7 - Math.max(0, Math.min(7, stats.currentStreak)); return <span key={index} className={active ? 'day-active' : ''}><i>{active ? '✓' : ''}</i><small>{['M', 'T', 'W', 'T', 'F', 'S', 'S'][index]}</small></span>; })}</div><div className="streak-record"><span>Longest streak</span><strong>{stats.longestStreak} days</strong></div></article>
    </div>
    <details className="panel readiness-explainability"><summary><span><span className="eyebrow">TRANSPARENT SCORE</span><strong>Career readiness by skill</strong></span><span className="readiness-explain-summary">{gap?.readinessBreakdown?.length || 0} required skills · {gap?.careerReadiness || 0}% readiness</span></summary><p className="muted-note">Each skill contributes its domain importance, state confidence, freshness, and relative demand across open YESGAP opportunities. This is a platform-relative signal, not an external labor-market measure. Skill gap and skill completion remain separate measures.</p><div className="readiness-breakdown-scroll"><table className="readiness-breakdown-table"><thead><tr><th>Required skill</th><th>Importance</th><th>State</th><th>Confidence</th><th>Freshness</th><th>Platform-relative demand</th><th>Score points</th></tr></thead><tbody>{(gap?.readinessBreakdown || []).map((row) => <tr key={row.skillId}><td><strong>{row.skillName}</strong></td><td>{row.importanceWeight}/5 · {row.importanceLevel}</td><td>{row.state}</td><td>{Number(row.confidenceMultiplier).toFixed(2)}</td><td>{Number(row.freshnessDecayFactor).toFixed(2)}{row.inactiveDays !== null ? ` · ${row.inactiveDays}d idle` : ''}</td><td>{Number(row.marketDemandMultiplier).toFixed(2)} · {row.marketOpportunityCount} open opportunities</td><td>{Number(row.readinessContribution).toFixed(1)}%</td></tr>)}</tbody></table></div><small className="muted-note">Platform opportunity data last recalculated {gap?.readinessModel?.marketDemandComputedAt ? new Date(gap.readinessModel.marketDemandComputedAt).toLocaleString() : 'during startup'}.</small></details>
    <div className="stat-grid four-stats"><StatCard label="Skills established" value={mastered.length} detail="Known or completed" icon={Layers3} tone="mint" /><StatCard label="Learning in progress" value={focus.length} detail="Skills you have started" icon={BookOpen} tone="blue" /><StatCard label="Coding problems" value={stats.codingProblemsSolved || 0} detail="Accepted submissions" icon={Code2} tone="violet" /><StatCard label="Assessment average" value={`${stats.averageAssessmentScore || 0}%`} detail={`${stats.testsCompleted || 0} attempts completed`} icon={Award} tone="amber" /></div>
    <div className="dashboard-lower-grid"><section className="panel skill-panel"><SectionHeading eyebrow="YOUR SKILL PROFILE" title="Skills for your path" description={user.careerDomain?.name || 'Select a career domain in your profile to see required skills.'} action={<Link className="small-link" to="/student/skills">All skills<ArrowRight size={14} /></Link>} />{skills.length ? <><div className="skill-summary-strip"><span><i className="legend-dot dot-strong" />{mastered.length} established</span><span><i className="legend-dot dot-progress" />{focus.length} in progress</span><span><i className="legend-dot dot-gap" />{missing.length} to explore</span></div><div className="compact-skill-list">{skills.slice(0, 6).map(({ skill, status, progress }) => <Link to={`/student/skills/${skill._id}`} className="compact-skill" key={skill._id}><span className={`skill-status-icon state-${status}`}>{status === 'known' || status === 'completed' ? <Check size={13} /> : status === 'in-progress' ? <Activity size={13} /> : <span />}</span><span className="compact-skill-name"><strong>{skill.name}</strong><small>{statusLabel(status)}</small></span><div className="compact-progress"><ProgressBar value={status === 'known' || status === 'completed' ? 100 : progress} tone={status === 'missing' ? 'rose' : status === 'in-progress' ? 'amber' : 'mint'} /></div><ChevronRight size={15} /></Link>)}</div></> : <EmptyState icon={Target} title="Choose a direction" description="Your career domain builds a skill gap and learning roadmap." />}</section>
      <section className="panel activity-panel">
        <SectionHeading eyebrow="RECENT ACTIVITY" title="Your week" description="Learning and practice, day by day." />
        <div className="activity-chart" role="img" aria-label="Learning activity for the last seven days"><div className="activity-bars">{activityDays.map(({ day, learn }) => <div className="activity-day" key={day}><div className="activity-bar-track"><span title={`${learn} learning sessions`} style={{ height: learn ? `${Math.max(5, (learn / peakActivity) * 100)}%` : '0%' }} /></div><span className="activity-day-label">{day}</span></div>)}</div></div>
        <div className="activity-legend"><span><i className="legend-dot dot-strong" />Learning sessions</span><span><TrendingUp size={14} />{stats.lessonsCompleted || 0} lessons completed</span></div>
        <div className="activity-breakdown">
          <div className="activity-breakdown-heading"><div><span>SKILL SNAPSHOT</span><h3>Skills by status</h3></div><Link to="/student/skills">View skills<ArrowRight size={13} /></Link></div>
          {skills.length ? <div className="skill-status-breakdown">
            <div className="skill-status-chart" role="img" aria-label={`${mastered.length} established, ${focus.length} in progress, ${missing.length} to explore`}>
              <div className="skill-status-donut" style={{ background: `conic-gradient(${skillChartStops})` }} />
              <div className="skill-chart-center"><strong>{skills.length}</strong><span>total skills</span></div>
            </div>
            <div className="skill-status-legend">{skillStatusData.map((item) => <div key={item.label}><i style={{ background: item.color }} /><span>{item.label}</span><strong>{item.value}</strong></div>)}</div>
          </div> : <p className="skill-status-empty">Choose a career domain to see the status of your skills here.</p>}
        </div>
      </section></div>
    <div className="dashboard-recommend-grid"><section className="panel recommendation-panel"><SectionHeading eyebrow="A GOOD NEXT STEP" title="Recommended learning" action={<Link className="small-link" to="/student/learning">Learning studio<ArrowRight size={14} /></Link>} />{(data.recommendedModules || []).slice(0, 3).map((module, index) => <Link className="recommendation-row" key={module._id} to={`/student/skills/${module.skill?._id}`}><div className={`recommend-number rec-${index}`}>0{index + 1}</div><div><strong>{module.title}</strong><small>{module.skill?.name || 'Learning module'} · {module.estimatedMinutes || 20} min</small></div><ArrowUpRight size={16} /></Link>)}{!data.recommendedModules?.length && <p className="muted-note">Learning modules will appear here as you choose a career path.</p>}</section><section className="opportunity-promo"><div className="promo-art"><BriefcaseBusiness size={23} /><span>✦</span><i /><i /></div><div className="eyebrow">YOUR NEXT OPPORTUNITY</div><h2>Ready to take the next step?</h2><p>Explore roles and invitations from teams looking for early-career talent.</p><Link to="/student/opportunities" className="button button-cream">Explore opportunities<ArrowRight size={15} /></Link><div className="promo-count"><strong>{stats.opportunitiesReceived || 0}</strong><span>invitations in your inbox</span></div></section></div>
  </PageFrame>;
}

function CompanyDashboard({ data, user }) {
  const stats = data.stats || {};
  return <PageFrame><div className="dashboard-welcome"><div><div className="eyebrow">HIRING WORKSPACE</div><h1>Welcome, {user.companyName || user.fullName}</h1><p>Find promising early-career talent and build a thoughtful hiring process.</p></div><Link to="/company/opportunities" className="button button-primary"><Plus size={16} />Create opportunity</Link></div><div className="stat-grid four-stats"><StatCard label="Open opportunities" value={stats.openOpportunities || 0} detail="Visible to candidates" icon={BriefcaseBusiness} tone="mint" /><StatCard label="Awaiting a response" value={stats.pendingResponses || 0} detail="Candidate invitations" icon={Clock3} tone="amber" /><StatCard label="Candidates accepted" value={stats.acceptedCandidates || 0} detail="Contact is unlocked" icon={CheckCircle2} tone="blue" /><StatCard label="Discoverable talent" value={stats.discoverableCandidates || 0} detail="Privacy-protected profiles" icon={UsersRound} tone="violet" /></div><div className="dashboard-lower-grid company-dashboard-grid"><section className="panel"><SectionHeading eyebrow="CANDIDATE DISCOVERY" title="Meet people with potential" description="Browse candidates by career path and their demonstrated skills." action={<Link to="/company/candidates" className="small-link">Find candidates<ArrowRight size={14} /></Link>} /><div className="discovery-preview"><div className="preview-avatar">YS</div><div><strong>Skill-based candidate profiles</strong><p>Compare domain knowledge, learning activity and assessment results.</p></div><ShieldCheck size={18} /></div><Link className="button button-soft full-button" to="/company/candidates">Open candidate discovery<ArrowRight size={15} /></Link></section><section className="panel company-setup-card"><div className="company-setup-icon"><Building2 size={21} /></div><div className="eyebrow">YOUR COMPANY PROFILE</div><h2>Make your opportunity clear.</h2><p>A complete company profile helps candidates understand the team and the work.</p><Link className="text-link" to="/company/profile">Review company profile<ArrowRight size={15} /></Link></section></div></PageFrame>;
}

function AdminDashboard({ data }) {
  const stats = data.stats || {};
  return <PageFrame><div className="dashboard-welcome"><div><div className="eyebrow">PLATFORM HEALTH</div><h1>Administration overview</h1><p>Monitor registrations, maintain shared learning content and respond to learner support requests.</p></div><Link className="button button-primary" to="/admin/approvals">Review approvals<span className="button-count">{stats.pendingCompanies || 0}</span><ArrowRight size={15} /></Link></div><div className="stat-grid four-stats"><StatCard label="Students" value={stats.students || 0} detail="Registered learner profiles" icon={GraduationCap} tone="mint" /><StatCard label="Companies" value={stats.companies || 0} detail="Hiring workspaces" icon={Building2} tone="blue" /><StatCard label="Pending approvals" value={stats.pendingCompanies || 0} detail="Need administrator review" icon={ShieldCheck} tone="amber" /><StatCard label="Open complaints" value={stats.openComplaints || 0} detail="Open or in review" icon={MessageSquareWarning} tone="rose" /></div><div className="admin-shortcut-grid"><AdminShortcut to="/admin/domains" icon={Layers3} title="Career domains" value={stats.domains || 0} detail="Manage career paths" /><AdminShortcut to="/admin/skills" icon={Sparkles} title="Skills catalog" value={stats.skills || 0} detail="Shared skill source" /><AdminShortcut to="/admin/complaints" icon={MessageSquareWarning} title="Support inbox" value={stats.openComplaints || 0} detail="Review learner reports" /><AdminShortcut to="/admin/activity" icon={FileText} title="Audit trail" value="View" detail="See recent platform changes" /></div><section className="panel audit-preview"><SectionHeading eyebrow="PLATFORM GOVERNANCE" title="Recent administrator actions" action={<Link className="small-link" to="/admin/activity">Open audit trail<ArrowRight size={14} /></Link>} />{data.recentActivity?.length ? data.recentActivity.slice(0, 6).map((row) => <div className="audit-row" key={row._id}><div className="audit-dot"><ShieldCheck size={14} /></div><div><strong>{row.description || statusLabel(row.action)}</strong><small>{row.actor?.fullName || 'Administrator'} · {new Date(row.createdAt).toLocaleString()}</small></div><Badge tone="neutral">{auditLabel(row)}</Badge></div>) : <EmptyState icon={FileText} title="No actions recorded yet" description="Privileged admin changes will be shown here." />}</section></PageFrame>;
}
function AdminShortcut({ to, icon: Icon, title, value, detail }) { return <Link to={to} className="admin-shortcut"><div className="admin-shortcut-icon"><Icon size={17} /></div><span>{title}</span><strong>{value}</strong><small>{detail}</small><ChevronRight size={15} /></Link>; }

function SkillCatalog({ user }) {
  const [query, setQuery] = useState(''); const [domainId, setDomainId] = useState(''); const [category, setCategory] = useState(''); const [difficulty, setDifficulty] = useState(''); const [status, setStatus] = useState('all'); const [saving, setSaving] = useState('');
  const { data: skills, loading, error, reload } = useApiData(`/catalog/skills${domainId ? `?domain=${domainId}` : ''}`);
  const { data: domains } = useApiData('/catalog/domains');
  const { data: profile, reload: reloadProfile } = useApiData('/student/profile');
  const skillStatus = useMemo(() => new Map((profile?.skills || []).map((row) => [String(row.skill?._id || row.skill), row])), [profile]);
  const filtered = (skills || []).filter((skill) => {
    const row = skillStatus.get(String(skill._id));
    const activeStatus = row?.status || 'missing';
    return matchesSearch(query, skill.name, skill.shortDescription, skill.description, skill.category, skill.tags, skill.supportedLanguages) && (!category || skill.category === category) && (!difficulty || skill.difficulty === difficulty) && (status === 'all' || activeStatus === status);
  });
  const categories = Array.from(new Set((skills || []).map((item) => item.category).filter(Boolean))).sort();
  const saveStatus = async (skill, next) => {
    setSaving(String(skill._id));
    try { await api.put(`/student/skills/${skill._id}`, { status: next }); await reloadProfile(); }
    finally { setSaving(''); }
  };
  return <PageFrame><SectionHeading eyebrow="YOUR SHARED SKILL CATALOG" title="Find your next skill" description="Every skill in YESGAP comes from one shared catalog, connected to career paths and learning materials." action={<span className="catalog-count">{skills?.length || 0} skills</span>} /><div className="filter-bar"><label className="search-field"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search skills or topics" aria-label="Search skills" /></label><label className="filter-field"><Filter size={15} /><select value={domainId} onChange={(event) => setDomainId(event.target.value)} aria-label="Filter by career domain"><option value="">All career paths</option>{(domains || []).map((item) => <option value={item._id} key={item._id}>{item.name}</option>)}</select></label><select className="filter-select" value={category} onChange={(event) => setCategory(event.target.value)} aria-label="Filter by skill category"><option value="">All categories</option>{categories.map((item) => <option key={item} value={item}>{item}</option>)}</select><select className="filter-select" value={difficulty} onChange={(event) => setDifficulty(event.target.value)} aria-label="Filter by difficulty"><option value="">All levels</option>{['beginner', 'intermediate', 'advanced'].map((item) => <option key={item} value={item}>{item}</option>)}</select></div><div className="status-filter-row">{['all', 'known', 'in-progress', 'completed', 'missing'].map((item) => <button key={item} className={`filter-pill ${status === item ? 'active' : ''}`} onClick={() => setStatus(item)}>{item === 'all' ? 'All skills' : statusLabel(item)}</button>)}</div>{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : <div className="catalog-grid">{filtered.map((skill) => { const row = skillStatus.get(String(skill._id)); const activeStatus = row?.status || 'missing'; return <article className="catalog-card" key={skill._id}><Link className="catalog-card-main" to={`/student/skills/${skill._id}`}><div className="catalog-card-top"><span className={`skill-monogram skill-tone-${skill.category?.split(' ')[0] || 'other'}`}>{skill.name.slice(0, 2).toUpperCase()}</span><Badge tone={statusTone(activeStatus)}>{statusLabel(activeStatus)}</Badge></div><h3>{skill.name}</h3><p>{skill.shortDescription}</p><div className="catalog-meta"><span>{skill.category}</span><span className="meta-dot">·</span><span>{skill.difficulty}</span></div>{activeStatus !== 'missing' && <ProgressBar value={activeStatus === 'known' || activeStatus === 'completed' ? 100 : row?.progress} tone={activeStatus === 'in-progress' ? 'amber' : 'mint'} />}</Link><div className="catalog-card-bottom"><Link to={`/student/skills/${skill._id}`} className="text-link">Explore skill<ArrowRight size={14} /></Link><div className="quick-status"><button title="Mark as known" aria-label={`Mark ${skill.name} as known`} disabled={saving === String(skill._id)} onClick={() => saveStatus(skill, activeStatus === 'known' ? 'missing' : 'known')}>{activeStatus === 'known' ? <CheckCircle2 size={16} /> : <Check size={16} />}</button><button title="Start learning" aria-label={`Start learning ${skill.name}`} onClick={() => saveStatus(skill, 'in-progress')}><BookOpenCheck size={16} /></button></div></div></article>; })}{!filtered.length && <div className="catalog-empty"><EmptyState icon={Search} title="No skills match those filters" description="Try a different search or clear one of the filters." action={{ label: 'Clear filters', onClick: () => { setQuery(''); setDomainId(''); setCategory(''); setDifficulty(''); setStatus('all'); } }} /></div>}</div>}</PageFrame>;
}

function Roadmap() {
  const { data, loading, error, reload } = useApiData('/student/roadmap');
  const skills = data?.skills || [];
  const columns = [
    { id: 'known', title: 'Established', status: ['known', 'completed', 'verified'], tone: 'green', subtitle: 'Build on your strengths.' },
    { id: 'in-progress', title: 'In progress', status: ['in-progress'], tone: 'amber', subtitle: 'Keep the momentum going.' },
    { id: 'missing', title: 'Up next', status: ['missing'], tone: 'rose', subtitle: 'Recommended next skills.' },
  ];
  return <PageFrame><SectionHeading eyebrow="BUILT FROM YOUR CAREER DOMAIN" title="A roadmap that grows with you" description="Your required skills are ordered by the career domain. Start with one step and update the path as you learn." action={<Link to="/student/profile" className="button button-soft">Change career path<ArrowRight size={15} /></Link>} />{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : !skills.length ? <EmptyState icon={Target} title="Choose your career direction" description="Your profile needs a career domain before YESGAP can build your roadmap." action={{ label: 'Choose a career path', onClick: () => window.location.assign('/student/profile') }} /> : <>
    <div className="roadmap-summary"><div className="roadmap-summary-main"><div className="eyebrow">YOUR ROADMAP</div><strong>{skills.length}<small> required skills</small></strong><p>Follow the sequence or open any skill to see its learning, practice and assessment options.</p><div className="readiness-meta"><span>Career readiness <strong>{data.careerReadiness}%</strong></span><span>Skill gap <strong>{data.skillGapPercentage}%</strong></span></div></div><div className="roadmap-summary-progress"><div className="roadmap-percent">{data.skillCompletionPercentage}<small>%</small></div><span>Skill completion</span><ProgressBar value={data.skillCompletionPercentage} /></div></div>
    <div className="roadmap-columns">{columns.map((column) => { const items = skills.filter((item) => column.status.includes(item.status)); return <section className={`roadmap-column roadmap-${column.tone}`} key={column.id}><div className={`roadmap-column-head roadmap-${column.tone}`}><div><span>{column.title}</span><small>{column.subtitle}</small></div><Badge tone={column.tone}>{items.length}</Badge></div><div className="roadmap-cards">{items.length ? items.map((item) => <Link className="roadmap-card" key={item.skill._id} to={`/student/skills/${item.skill._id}`}><div className="roadmap-card-top"><span className={`roadmap-step step-${column.tone}`}>{column.id === 'missing' ? String(skills.filter((row) => row.status === 'missing').indexOf(item) + 1).padStart(2, '0') : '✓'}</span><div><strong>{item.skill.name}</strong><small>{item.skill.category} · {item.skill.difficulty}</small></div><ChevronRight size={15} /></div>{item.recommendedModule && <div className="roadmap-recommend"><BookOpen size={14} /><span><small>Recommended learning</small><strong>{item.recommendedModule.title}</strong></span></div>}{column.id === 'in-progress' && <ProgressBar value={item.progress} tone="amber" />}</Link>) : <div className="roadmap-empty">Nothing here yet.</div>}</div></section>; })}</div>
    <div className="readiness-method-note"><CircleHelp size={17} /><div><strong>How career readiness is calculated</strong><p>For each required skill, YESGAP multiplies its domain-specific importance, state confidence, freshness factor, and relative platform-demand multiplier. The skill gap and skill completion values above continue to use their existing calculations.</p></div></div>
  </>}</PageFrame>;
}
function LearningHome() {
  const { data, loading, error, reload } = useApiData('/student/learning');
  if (loading) return <PageFrame><Loading /></PageFrame>;
  if (error) return <PageFrame><ErrorNotice message={error} onRetry={reload} /></PageFrame>;
  const modules = data?.modules || [];
  return <PageFrame><SectionHeading eyebrow="IN-PORTAL LEARNING" title="Learning studio" description="Lessons and examples live in YESGAP and connect back to your career skill plan." action={<Link className="button button-soft" to="/student/skills">Browse skills<Layers3 size={15} /></Link>} /><div className="learning-callout"><div className="learning-callout-icon"><BookOpenCheck size={22} /></div><div><div className="eyebrow">LEARN WITH A PURPOSE</div><h2>Every lesson is connected to a skill.</h2><p>Pick up where you left off or explore material for another skill in your path.</p></div><Link to="/student/roadmap" className="button button-cream">Open my roadmap<ArrowRight size={15} /></Link></div><SectionHeading eyebrow="SUGGESTED FOR YOUR CAREER PATH" title="Continue learning" />{modules.length ? <div className="module-grid">{modules.map((module, index) => <Link to={`/student/skills/${module.skill?._id}`} className="module-card" key={module._id}><div className="module-card-meta"><span className={`module-index module-index-${index % 4}`}>0{index + 1}</span><Badge tone={index ? 'neutral' : 'blue'}>{module.level || 'beginner'}</Badge></div><h3>{module.title}</h3><p>{module.description}</p><div className="module-card-footer"><span>{module.skill?.name}</span><span><Clock3 size={13} />{module.estimatedMinutes || 20} min</span></div><ProgressBar value={0} /></Link>)}</div> : <EmptyState icon={BookOpen} title="No lessons in this career path yet" description="Choose a skill to browse the learning materials available in the portal." action={{ label: 'Browse the skill library', onClick: () => window.location.assign('/student/skills') }} />}</PageFrame>;
}

function StudentOpportunities() {
  const [refreshKey, setRefreshKey] = useState(0); const [error, setError] = useState(''); const [busy, setBusy] = useState(''); const [roleQuery, setRoleQuery] = useState('');
  const { data: applications, loading: appLoading, reload: reloadApps } = useApiData(`/student/applications?refresh=${refreshKey}`);
  const { data: opportunities, loading: jobsLoading, reload: reloadJobs } = useApiData('/student/opportunities?limit=40');
  const update = async (id, response) => { setBusy(id); setError(''); try { await api.post(`/student/applications/${id}/respond`, { response }); await reloadApps(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(''); } };
  const apply = async (id) => { setBusy(id); setError(''); try { await api.post(`/student/opportunities/${id}/apply`); await reloadApps(); await reloadJobs(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(''); } };
  const withdraw = async (id) => { setBusy(id); try { await api.post(`/student/applications/${id}/withdraw`); await reloadApps(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(''); } };
  const hasApplication = new Set((applications || []).map((row) => String(row.opportunity?._id || row.opportunity))); const visibleOpportunities = (opportunities || []).filter((job) => matchesSearch(roleQuery, job.title, job.company?.companyName, job.company?.industry, job.description, job.location, job.workMode, job.employmentType, job.requiredSkills?.map((skill) => skill.name)));
  return <PageFrame className="student-opportunities-page"><SectionHeading eyebrow="YOUR CAREER NEXT STEP" title="Opportunities" description="Explore roles from approved companies or respond to an invitation in your inbox." /><div className="opportunity-section-title"><div><h2>Your invitations</h2><p>Companies only see your contact details after you accept.</p></div><Badge tone="blue">{applications?.filter((row) => row.status === 'offered').length || 0} waiting</Badge></div>{error && <ErrorNotice message={error} />}{appLoading ? <Loading /> : applications?.length ? <div className="application-list">{applications.map((application) => <article className="application-card" key={application._id}><div className="company-avatar">{initials(application.company?.companyName || 'Company')}</div><div className="application-main"><div className="application-meta"><Badge tone={statusTone(application.status)}>{statusLabel(application.status)}</Badge><span>{new Date(application.createdAt).toLocaleDateString()}</span></div><h3>{application.opportunity?.title || 'Opportunity'}</h3><p>{application.company?.companyName} · {application.opportunity?.location || application.company?.location || 'India'} · {application.opportunity?.compensation || 'Compensation discussed during hiring'}</p><div className="skill-tag-row">{application.opportunity?.requiredSkills?.slice(0, 5).map((skill) => <span className="skill-tag" key={skill._id}>{skill.name}</span>)}</div>{application.status === 'accepted' && <p className="unlock-note"><ShieldCheck size={14} /> Your profile and contact details are shared with this company.</p>}</div><div className="application-actions">{application.status === 'offered' && <><button className="button button-primary button-small" disabled={busy === application._id} onClick={() => update(application._id, 'accepted')}>Accept</button><button className="button button-quiet button-small" disabled={busy === application._id} onClick={() => update(application._id, 'rejected')}>Decline</button></>}{['accepted', 'in-progress'].includes(application.status) && <button className="button button-quiet button-small" disabled={busy === application._id} onClick={() => withdraw(application._id)}>Withdraw</button>}</div></article>)}</div> : <div className="opportunity-empty-state"><BriefcaseBusiness size={16} /><span>No invitations yet. Browse open roles below, or check your inbox when a company reaches out.</span></div>}
    <div className="opportunity-section-title open-roles-title"><div><h2>Open roles</h2><p>Choose a role that fits your direction and interests.</p></div><span className="subtle-label">{opportunities?.length || 0} currently open</span></div>{opportunities?.length > 0 && <div className="opportunity-search-row"><label className="search-field opportunity-search"><Search size={17} /><input aria-label="Search open roles" value={roleQuery} onChange={(event) => setRoleQuery(event.target.value)} placeholder="Search by role, company, skill, or location" /></label><span>{roleQuery ? `${visibleOpportunities.length} matching roles` : `${opportunities.length} roles`}</span></div>}{jobsLoading ? <Loading /> : visibleOpportunities.length ? <div className="role-grid">{visibleOpportunities.map((job) => { const applied = hasApplication.has(String(job._id)); return <article className="role-card" key={job._id}><div className="role-card-top"><div className="company-avatar company-avatar-color">{initials(job.company?.companyName || 'Y')}</div><Badge tone="green">Open</Badge></div><h3>{job.title}</h3><p className="role-company">{job.company?.companyName} · {job.company?.industry || 'Technology'}</p><p className="role-description">{job.description || 'An opportunity to grow through real product work with a supportive team.'}</p><div className="role-attributes"><span>{job.location || 'India'}</span><span>{job.workMode || 'Hybrid'}</span><span>{job.employmentType || 'Full-time'}</span></div><div className="skill-tag-row">{job.requiredSkills?.slice(0, 4).map((skill) => <span className="skill-tag" key={skill._id}>{skill.name}</span>)}</div><button className={`button ${applied ? 'button-soft' : 'button-primary'} full-button`} disabled={applied || busy === job._id} onClick={() => apply(job._id)}>{applied ? 'Application sent' : 'Apply to this role'}{applied ? <Check size={15} /> : <ArrowRight size={15} />}</button></article>; })}</div> : roleQuery ? <EmptyState icon={Search} title="No matching roles" description="Try another title, company, skill, or location." /> : <EmptyState icon={BriefcaseBusiness} title="No open roles to show" description="Approved companies will post new opportunities here." />}</PageFrame>;
}

function CompanyOpportunities() {
  const [refreshKey, setRefreshKey] = useState(0); const [showCreate, setShowCreate] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [busy, setBusy] = useState(false);
  const { data, loading, reload } = useApiData(`/company/opportunities?refresh=${refreshKey}`);
  const { data: catalog } = useApiData('/catalog/skills');
  const [values, setValues] = useState({ title: '', description: '', compensation: '', location: '', workMode: 'hybrid', employmentType: 'full-time', requiredSkills: [], firstRound: { type: 'technical', name: 'Portfolio and fundamentals review', durationMinutes: 30 } });
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value }));
  const toggle = (id) => setValues((current) => ({ ...current, requiredSkills: current.requiredSkills.includes(id) ? current.requiredSkills.filter((item) => item !== id) : [...current.requiredSkills, id] }));
  const create = async (event) => { event.preventDefault(); setBusy(true); setError(''); setNotice(''); try { await api.post('/company/opportunities', values); setNotice('Your opportunity is live. Invite candidates from Candidate discovery.'); setShowCreate(false); await reload(); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  const setStatus = async (row, status) => { setError(''); try { await api.patch(`/company/opportunities/${row._id}/status`, { status }); await reload(); } catch (reason) { setError(errorMessage(reason)); } };
  return <PageFrame className="company-opportunities-page"><SectionHeading eyebrow="YOUR OPENINGS" title="Opportunities" description="Publish a clear role, choose skills from the shared catalog and invite candidates when ready." action={<button className="button button-primary" onClick={() => setShowCreate(true)}><Plus size={16} />Create opportunity</button>} />{notice && <div className="notice success-notice"><CheckCircle2 size={16} />{notice}<button onClick={() => setNotice('')}><X size={14} /></button></div>}{error && <ErrorNotice message={error} />}{loading ? <Loading /> : data?.length ? <div className="company-opening-list">{data.map((job) => <article className="opening-card" key={job._id}><div className="opening-icon"><BriefcaseBusiness size={18} /></div><div className="opening-details"><div className="opening-meta"><Badge tone={statusTone(job.status)}>{statusLabel(job.status)}</Badge><span>{[job.location || 'Location flexible', statusLabel(job.workMode), statusLabel(job.employmentType)].filter(Boolean).join(' · ')}</span></div><h3>{job.title}</h3><p>{job.description}</p><div className="skill-tag-row">{job.requiredSkills?.map((skill) => <span className="skill-tag" key={skill._id}>{skill.name}</span>)}</div><small className="opening-date">Published {new Date(job.createdAt).toLocaleDateString('en-IN', { day: 'numeric', month: 'short', year: 'numeric' })} · {job.openings} opening{job.openings === 1 ? '' : 's'}</small></div><div className="opening-actions">{job.status === 'open' ? <button className="button button-soft button-small" onClick={() => setStatus(job, 'closed')}>Close role</button> : job.status === 'closed' ? <button className="button button-soft button-small" onClick={() => setStatus(job, 'open')}>Reopen role</button> : null}{job.status !== 'filled' && <button className="button button-quiet button-small" onClick={() => setStatus(job, 'filled')}>Mark filled</button>}</div></article>)}</div> : <div className="panel"><EmptyState icon={BriefcaseBusiness} title="No opportunities yet" description="Create your first role and invite candidates when the profile looks right." action={{ label: 'Create an opportunity', onClick: () => setShowCreate(true) }} /></div>}
    {showCreate && <Modal title="Create an opportunity" onClose={() => setShowCreate(false)}><form className="modal-form" onSubmit={create}><Field label="Role title"><FormInput required name="title" value={values.title} onChange={update} placeholder="Associate Software Engineer" /></Field><Field label="Role description"><textarea className="input textarea" required rows="4" name="description" value={values.description} onChange={update} placeholder="What this person will work on and learn" /></Field><Field label="Responsibilities"><textarea className="input textarea" rows="2" name="responsibilities" value={values.responsibilities || ''} onChange={update} placeholder="Core responsibilities" /></Field><div className="form-grid"><Field label="Compensation"><FormInput name="compensation" value={values.compensation} onChange={update} placeholder="₹6–10 LPA" /></Field><Field label="Location"><FormInput name="location" value={values.location} onChange={update} placeholder="Bengaluru / Remote" /></Field></div><div className="form-grid"><Field label="Work mode"><FormSelect name="workMode" value={values.workMode} onChange={update}><option value="on-site">On-site</option><option value="hybrid">Hybrid</option><option value="remote">Remote</option></FormSelect></Field><Field label="Employment type"><FormSelect name="employmentType" value={values.employmentType} onChange={update}><option value="full-time">Full-time</option><option value="internship">Internship</option><option value="part-time">Part-time</option><option value="contract">Contract</option></FormSelect></Field></div><Field label="Required skills" hint="Choose exact entries from the central skills catalog."><div className="skill-select-grid modal-skill-grid">{(catalog || []).map((skill) => <button type="button" className={`skill-select-chip ${values.requiredSkills.includes(skill._id) ? 'selected' : ''}`} key={skill._id} onClick={() => toggle(skill._id)}>{values.requiredSkills.includes(skill._id) && <Check size={13} />}{skill.name}</button>)}</div></Field><div className="form-grid"><Field label="First round type"><FormSelect value={values.firstRound.type} onChange={(event) => setValues((current) => ({ ...current, firstRound: { ...current.firstRound, type: event.target.value } }))}><option value="technical">Technical conversation</option><option value="mcq">Multiple choice assessment</option><option value="face-to-face">Face-to-face interview</option><option value="video-interview">Video interview</option></FormSelect></Field><Field label="First round name"><FormInput value={values.firstRound.name} onChange={(event) => setValues((current) => ({ ...current, firstRound: { ...current.firstRound, name: event.target.value } }))} /></Field></div>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={() => setShowCreate(false)}>Cancel</button><button disabled={busy || !values.requiredSkills.length} className="button button-primary">{busy ? 'Publishing…' : 'Publish role'}<ArrowRight size={15} /></button></div></form></Modal>}
  </PageFrame>;
}

function CandidateDiscovery() {
  const { data: domains } = useApiData('/catalog/domains'); const { data: skills } = useApiData('/catalog/skills'); const { data: opportunities, reload: reloadOpportunities } = useApiData('/company/opportunities');
  const [query, setQuery] = useState(''); const [domainId, setDomainId] = useState(''); const [skillId, setSkillId] = useState(''); const [refresh, setRefresh] = useState(0); const [inviting, setInviting] = useState(''); const [selectedCandidate, setSelectedCandidate] = useState(null); const [error, setError] = useState(''); const [notice, setNotice] = useState('');
  const params = new URLSearchParams(); if (query) params.set('q', query); if (domainId) params.set('domainId', domainId); if (skillId) params.set('skillId', skillId); params.set('limit', '60'); params.set('page', '1');
  const { data: candidates, loading, reload } = useApiData(`/company/candidates?${params.toString()}&refresh=${refresh}`);
  const openJobs = (opportunities || []).filter((row) => row.status === 'open');
  const invite = async (candidateId) => {
    if (!openJobs.length) { setError('Create an open opportunity before inviting candidates.'); return; }
    setInviting(candidateId); setError(''); setNotice('');
    try { await api.post(`/company/opportunities/${openJobs[0]._id}/send`, { studentId: candidateId }); setNotice('Invitation sent to the candidate’s YESGAP inbox.'); setRefresh((value) => value + 1); await reloadOpportunities(); }
    catch (reason) { setError(errorMessage(reason)); }
    finally { setInviting(''); }
  };
  return <PageFrame className="candidate-discovery-page"><SectionHeading eyebrow="SKILL-BASED DISCOVERY" title="Find people with potential" description="Explore public candidate profiles by career domain, skills and demonstrated learning. Contact details stay private until a candidate accepts." action={<Link className="button button-soft" to="/company/opportunities">Your openings<BriefcaseBusiness size={15} /></Link>} /><div className="candidate-filter-grid"><label className="search-field"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search candidates by name" aria-label="Search candidates" /></label><select className="filter-select" aria-label="Career domain" value={domainId} onChange={(event) => setDomainId(event.target.value)}><option value="">All career domains</option>{(domains || []).map((item) => <option value={item._id} key={item._id}>{item.name}</option>)}</select><select className="filter-select" aria-label="Candidate skill" value={skillId} onChange={(event) => setSkillId(event.target.value)}><option value="">Any skill</option>{(skills || []).map((item) => <option value={item._id} key={item._id}>{item.name}</option>)}</select></div>{error && <ErrorNotice message={error} />}{notice && <div className="notice success-notice"><CheckCircle2 size={16} />{notice}<button onClick={() => setNotice('')}><X size={14} /></button></div>}{loading ? <Loading /> : candidates?.length ? <div className="candidate-grid">{candidates.map((candidate) => <article className="candidate-card" key={candidate.id}><div className="candidate-card-head"><div className="candidate-avatar">{initials(candidate.fullName)}</div><div className="candidate-identity"><h3>{candidate.fullName}</h3><p>{candidate.careerDomain?.name || 'Career path not selected'}</p></div><button type="button" className="icon-button candidate-profile-trigger" aria-label={`View ${candidate.fullName} profile`} onClick={() => setSelectedCandidate(candidate)}><ArrowUpRight size={16} /></button></div><p className="candidate-headline">{candidate.headline || 'No headline shared yet.'}</p><div className="candidate-skill-list">{candidate.skills?.slice(0, 5).map((row) => <span className="skill-tag" key={row.skill?._id || row.skill}>{row.skill?.name || 'Skill'}<i>{row.readinessState === 'verified' || row.status === 'completed' || row.status === 'known' ? '✓' : row.status === 'in-progress' ? '·' : ''}</i></span>)}</div><div className="candidate-metrics"><span><BookOpen size={14} /><b>{candidate.learningProgress || 0}</b> {candidate.learningProgress === 1 ? 'lesson' : 'lessons'}</span><span><Award size={14} /><b>{candidate.assessmentPerformance || 0}%</b> average</span></div>{candidate.indicators?.length > 0 && <div className="indicator-row">{candidate.indicators.map((indicator) => <span key={indicator}><i />{indicator.replaceAll('-', ' ')}</span>)}</div>}<div className="candidate-card-footer"><span><ShieldCheck size={14} />Contact details private</span><button className="button button-primary button-small" disabled={inviting === candidate.id || !openJobs.length} onClick={() => invite(candidate.id)}>{inviting === candidate.id ? 'Sending…' : 'Invite'}<ArrowRight size={14} /></button></div></article>)}</div> : <EmptyState icon={UsersRound} title="No candidates match your filters" description="Try another skill or career domain. New learners join as they build their profiles." action={{ label: 'Clear filters', onClick: () => { setQuery(''); setDomainId(''); setSkillId(''); } }} />}{selectedCandidate && <Modal title="Candidate snapshot" onClose={() => setSelectedCandidate(null)}><div className="candidate-profile-dialog"><div className="candidate-profile-identity"><div className="candidate-avatar candidate-profile-avatar">{initials(selectedCandidate.fullName)}</div><div><div className="eyebrow">PUBLIC LEARNER PROFILE</div><h3>{selectedCandidate.fullName}</h3><p>{selectedCandidate.careerDomain?.name || 'Career path not selected'}</p></div></div><p className="candidate-profile-headline">{selectedCandidate.headline || 'This learner is building practical skills and experience.'}</p><div className="candidate-profile-stat-grid"><div><BookOpen size={17} /><strong>{selectedCandidate.learningProgress || 0}</strong><span>Lessons completed</span></div><div><Award size={17} /><strong>{selectedCandidate.assessmentPerformance || 0}%</strong><span>Assessment average</span></div></div><section className="candidate-profile-section"><div className="candidate-profile-section-head"><h4>Demonstrated skills</h4><span>{selectedCandidate.skills?.length || 0} shared</span></div><div className="candidate-profile-skills">{selectedCandidate.skills?.length ? selectedCandidate.skills.map((row, index) => <span className="candidate-detail-skill" key={row.skill?._id || row.skill || index}>{row.skill?.name || 'Skill'}<small>{row.readinessState === 'verified' ? 'Verified' : row.status === 'completed' ? 'Completed' : row.status === 'known' ? 'Known' : row.status === 'in-progress' ? 'In progress' : 'Building'}</small></span>) : <p>No skills are listed yet.</p>}</div></section>{selectedCandidate.indicators?.length > 0 && <div className="candidate-profile-indicators">{selectedCandidate.indicators.map((indicator) => <span key={indicator}><i />{indicator.replaceAll('-', ' ')}</span>)}</div>}<div className="candidate-profile-privacy"><ShieldCheck size={17} /><span><strong>Privacy protected</strong><small>Contact details stay private until the candidate accepts an invitation.</small></span></div><div className="modal-actions"><button type="button" className="button button-quiet" onClick={() => setSelectedCandidate(null)}>Close</button><button type="button" className="button button-primary" disabled={!openJobs.length || inviting === selectedCandidate.id} onClick={() => invite(selectedCandidate.id)}>{inviting === selectedCandidate.id ? 'Sending...' : 'Invite candidate'}<ArrowRight size={15} /></button></div></div></Modal>}</PageFrame>;
}

function Recruitment({ role }) {
  if (role === 'student') return <StudentRecruitment />;
  return <CompanyRecruitment />;
}

function CompanyRecruitment() {
  const { data, loading, error, reload } = useApiData('/company/applications');
  const [roundsByApplication, setRoundsByApplication] = useState({}); const [modalFor, setModalFor] = useState(null); const [busy, setBusy] = useState(''); const [message, setMessage] = useState('');
  useEffect(() => { (data || []).forEach((row) => { if (!roundsByApplication[row._id]) api.get(`/company/applications/${row._id}/rounds`).then((response) => setRoundsByApplication((current) => ({ ...current, [row._id]: dataOf(response) }))).catch(() => undefined); }); }, [data]);
  const refreshApplicationRounds = async () => { setRoundsByApplication({}); await reload(); };
  const record = async (roundId, result) => { setBusy(roundId); setMessage(''); try { await api.post(`/company/rounds/${roundId}/results`, { result, feedback: 'Thank you for taking part in this round. The company has recorded an outcome.' }); await reload(); setMessage('Round result saved and sent to the candidate inbox.'); } catch (reason) { setMessage(errorMessage(reason)); } finally { setBusy(''); } };
  return <PageFrame className="company-recruitment-page"><SectionHeading eyebrow="CANDIDATE PIPELINE" title="Recruitment" description="Review responses, schedule flexible rounds and send outcomes through the in-portal inbox." action={<Link to="/company/candidates" className="button button-soft">Find candidates<UsersRound size={15} /></Link>} />{message && <div className="notice success-notice"><CheckCircle2 size={16} />{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}{error && <ErrorNotice message={error} onRetry={reload} />}{loading ? <Loading /> : data?.length ? <div className="recruitment-list">{data.map((application) => <article className="recruitment-card" key={application._id}><div className="recruitment-candidate"><div className="candidate-avatar candidate-avatar-small">{initials(application.student?.fullName)}</div><div><h3>{application.student?.fullName}</h3><p>{application.opportunity?.title} · {application.student?.careerDomain?.name || 'Career path'}</p></div><Badge tone={statusTone(application.status)}>{statusLabel(application.status)}</Badge></div><div className="recruitment-private"><span><ShieldCheck size={14} />Candidate privacy</span>{application.student?.email ? <><a href={`mailto:${application.student.email}`}>{application.student.email}</a><span>{application.student.phone}</span>{application.student.resume?.fileId && <a href={`${import.meta.env.VITE_API_URL || '/api'}/resumes/${application.student.resume.fileId}`} target="_blank" rel="noreferrer">Resume ↗</a>}</> : <p>Contact details unlock after the candidate accepts this opportunity.</p>}</div><div className="rounds-head"><div><strong>Recruitment rounds</strong><small>{roundsByApplication[application._id]?.length || 0} {roundsByApplication[application._id]?.length === 1 ? 'scheduled stage' : 'scheduled stages'}</small></div>{['accepted', 'in-progress'].includes(application.status) && <button className="button button-soft button-small" onClick={() => setModalFor(application)}><Plus size={14} />Schedule round</button>}</div>{roundsByApplication[application._id]?.map((round) => <div className="round-row" key={round._id}><div className="round-number">{String(round.roundNumber).padStart(2, '0')}</div><div className="round-info"><strong>{round.name}</strong><small>{statusLabel(round.type)} · {round.date || 'Date to be confirmed'} {round.time ? `· ${round.time}` : ''}</small></div><Badge tone={statusTone(round.status)}>{statusLabel(round.status)}</Badge>{round.status !== 'completed' && <div className="round-outcome-actions"><button disabled={busy === round._id} onClick={() => record(round._id, 'passed')}>Pass</button><button disabled={busy === round._id} onClick={() => record(round._id, 'failed')}>Fail</button><button disabled={busy === round._id} onClick={() => record(round._id, 'next-round')}>Next</button></div>}</div>)}</article>)}</div> : <div className="panel"><EmptyState icon={ClipboardCheck} title="Your pipeline is ready" description="Publish a role and invite candidates to begin recruitment." action={{ label: 'Find candidates', onClick: () => window.location.assign('/company/candidates') }} /></div>}{modalFor && <RoundModal application={modalFor} onClose={() => setModalFor(null)} onCreated={refreshApplicationRounds} />}</PageFrame>;
}

function RoundModal({ application, onClose, onCreated }) {
  const { data: skills } = useApiData('/catalog/skills');
  const [values, setValues] = useState({ name: '', type: 'technical', date: '', time: '', durationMinutes: 30, instructions: '', skillId: '' });
  const [sets, setSets] = useState([]); const [bank, setBank] = useState([]); const [codingQuestions, setCodingQuestions] = useState([]); const [source, setSource] = useState('shared'); const [selectedQuestionIds, setSelectedQuestionIds] = useState([]);
  const [newQuestion, setNewQuestion] = useState({ prompt: '', options: '', correctNumber: '1', topic: '', difficulty: 'beginner', explanation: '' });
  const [questionBusy, setQuestionBusy] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [questionNotice, setQuestionNotice] = useState('');
  useEffect(() => {
    if (!values.skillId) { setSets([]); setBank([]); setCodingQuestions([]); return undefined; }
    let active = true;
    Promise.all([
      api.get(`/company/assessment-sets/${values.skillId}`),
      api.get(`/company/question-bank?skillId=${values.skillId}`),
      api.get(`/company/coding-questions/${values.skillId}`),
    ]).then(([setsResponse, bankResponse, codingResponse]) => {
      if (active) { const nextCoding = dataOf(codingResponse) || []; setSets(dataOf(setsResponse) || []); setBank(dataOf(bankResponse) || []); setCodingQuestions(nextCoding); setSelectedQuestionIds([]); setValues((current) => ({ ...current, codingQuestionId: nextCoding.some((question) => question._id === current.codingQuestionId) ? current.codingQuestionId : nextCoding[0]?._id || '' })); }
    }).catch(() => { if (active) { setSets([]); setBank([]); setCodingQuestions([]); } });
    return () => { active = false; };
  }, [values.skillId]);
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value }));
  const addCompanyQuestion = async () => {
    const options = newQuestion.options.split(/\r?\n/).map((value) => value.trim()).filter(Boolean);
    if (!values.skillId) { setError('Choose an assessment skill before adding a question.'); return; }
    if (!newQuestion.prompt.trim() || options.length < 2 || Number(newQuestion.correctNumber) < 1 || Number(newQuestion.correctNumber) > options.length) { setError('Add a question, at least two options, and choose a correct option number from that list.'); return; }
    setQuestionBusy(true); setError(''); setQuestionNotice('');
    try {
      const response = await api.post('/company/question-bank', { skillId: values.skillId, difficulty: newQuestion.difficulty, prompt: newQuestion.prompt, options, correctIndex: Number(newQuestion.correctNumber) - 1, topic: newQuestion.topic, explanation: newQuestion.explanation });
      const item = dataOf(response);
      setBank((current) => [item, ...current]); setSelectedQuestionIds((current) => [...new Set([...current, item._id])]); setSource('bank');
      setNewQuestion((current) => ({ ...current, prompt: '', options: '', explanation: '' })); setQuestionNotice('Private question saved and selected for this round.');
    } catch (reason) { setError(errorMessage(reason)); }
    finally { setQuestionBusy(false); }
  };
  const submit = async (event) => {
    event.preventDefault(); setBusy(true); setError('');
    if (values.type === 'coding' && !values.codingQuestionId) { setError('Choose a coding challenge for this round.'); setBusy(false); return; }
    if (['mcq', 'custom-assessment'].includes(values.type) && source === 'bank' && !selectedQuestionIds.length) { setError('Choose at least one question for this round.'); setBusy(false); return; }
    try {
      await api.post(`/company/applications/${application._id}/rounds`, {
        ...values, durationMinutes: Number(values.durationMinutes),
        testSetId: source === 'shared' ? values.testSetId || undefined : undefined,
        questionItems: source === 'bank' ? selectedQuestionIds : undefined,
        codingQuestionId: values.type === 'coding' ? values.codingQuestionId : undefined,
      });
      await onCreated(); onClose();
    } catch (reason) { setError(errorMessage(reason)); }
    finally { setBusy(false); }
  };
  const assessmentType = ['mcq', 'custom-assessment'].includes(values.type);
  const codingType = values.type === 'coding';
  return <Modal title={`Schedule a round · ${application.student?.fullName}`} onClose={onClose}><form className="modal-form" onSubmit={submit}>
    <Field label="Round name"><FormInput required name="name" value={values.name} onChange={update} placeholder="Technical conversation" /></Field>
    <div className="form-grid"><Field label="Round type"><FormSelect name="type" value={values.type} onChange={update}><option value="technical">Technical conversation</option><option value="mcq">Multiple choice assessment</option><option value="coding">Coding assessment</option><option value="face-to-face">Face-to-face interview</option><option value="video-interview">Video interview</option><option value="custom-assessment">Custom assessment</option></FormSelect></Field><Field label="Duration (minutes)"><FormInput type="number" min="1" max="600" name="durationMinutes" value={values.durationMinutes} onChange={update} /></Field></div>
    <div className="form-grid"><Field label="Date"><FormInput type="date" name="date" value={values.date} onChange={update} /></Field><Field label="Time"><FormInput type="time" name="time" value={values.time} onChange={update} /></Field></div>
    {(assessmentType || codingType) && <Field label="Assessment skill"><FormSelect name="skillId" value={values.skillId} onChange={update}><option value="">Choose a skill</option>{(skills || []).map((skill) => <option key={skill._id} value={skill._id}>{skill.name}</option>)}</FormSelect></Field>}
    {codingType && <Field label="Coding challenge"><FormSelect name="codingQuestionId" value={values.codingQuestionId || ''} onChange={update}><option value="">Choose a published coding challenge</option>{codingQuestions.map((question) => <option value={question._id} key={question._id}>{question.title} · {question.difficulty}{question.topic ? ` · ${question.topic}` : ''}</option>)}</FormSelect>{values.skillId && !codingQuestions.length && <small className="field-hint">No challenge is published for this skill yet. An admin can add one in Coding Problems.</small>}</Field>}
    {assessmentType && <>
      {values.skillId && <Field label="Question source"><FormSelect value={source} onChange={(event) => setSource(event.target.value)}><option value="shared">Shared assessment sets</option><option value="bank">Choose question-bank items</option></FormSelect></Field>}
      {source === 'shared' && <Field label="Shared question set"><FormSelect name="testSetId" value={values.testSetId || ''} onChange={update}><option value="">Choose a shared assessment</option>{sets.filter((set) => set.questionCount > 0).map((set) => <option value={set._id} key={set._id}>{set.title} · {set.questionCount} questions</option>)}</FormSelect></Field>}
      {source === 'bank' && values.skillId && <div className="company-question-picker"><strong>Select questions for this round</strong>{bank.length ? bank.map((item) => <label key={item._id}><input type="checkbox" checked={selectedQuestionIds.includes(item._id)} onChange={(event) => setSelectedQuestionIds((current) => event.target.checked ? [...current, item._id] : current.filter((id) => id !== item._id))} /><span><b>{item.prompt}</b><small>{item.visibility === 'company' ? 'Your private question' : 'Shared'} · {item.difficulty}{item.topic ? ` · ${item.topic}` : ''}</small></span></label>) : <p>No questions yet for this skill. Add a private question below or choose a shared test set.</p>}
        <div className="company-question-author"><div className="eyebrow">ADD A PRIVATE QUESTION</div><Field label="Question prompt"><FormInput value={newQuestion.prompt} onChange={(event) => setNewQuestion((current) => ({ ...current, prompt: event.target.value }))} /></Field><Field label="Answer options (one per line)"><textarea className="input textarea" rows="3" value={newQuestion.options} onChange={(event) => setNewQuestion((current) => ({ ...current, options: event.target.value }))} /></Field><div className="form-grid"><Field label="Correct option number"><FormInput type="number" min="1" max="6" value={newQuestion.correctNumber} onChange={(event) => setNewQuestion((current) => ({ ...current, correctNumber: event.target.value }))} /></Field><Field label="Difficulty"><FormSelect value={newQuestion.difficulty} onChange={(event) => setNewQuestion((current) => ({ ...current, difficulty: event.target.value }))}><option>beginner</option><option>intermediate</option><option>advanced</option></FormSelect></Field></div><Field label="Topic"><FormInput value={newQuestion.topic} onChange={(event) => setNewQuestion((current) => ({ ...current, topic: event.target.value }))} /></Field><Field label="Explanation"><textarea className="input textarea" rows="2" value={newQuestion.explanation} onChange={(event) => setNewQuestion((current) => ({ ...current, explanation: event.target.value }))} /></Field><button type="button" className="button button-soft button-small" disabled={questionBusy || !newQuestion.prompt.trim()} onClick={addCompanyQuestion}>{questionBusy ? 'Saving…' : 'Save and select question'}<Plus size={14} /></button></div></div>}
    </>}
    <Field label="Instructions"><textarea className="input textarea" name="instructions" rows="3" value={values.instructions} onChange={update} placeholder="Tell the candidate how to prepare or join" /></Field>
    {values.type === 'video-interview' && <Field label="Meeting link"><FormInput name="meetingLink" value={values.meetingLink || ''} onChange={update} placeholder="https://meeting.example" /></Field>}
    {questionNotice && <div className="form-alert form-alert-success">{questionNotice}</div>}{error && <div className="form-alert form-alert-error">{error}</div>}
    <div className="modal-actions"><button className="button button-quiet" type="button" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>{busy ? 'Saving…' : 'Schedule round'}<ArrowRight size={15} /></button></div>
  </form></Modal>;
}
function StudentRecruitment() {
  const { data, loading, error, reload } = useApiData('/student/rounds'); const [attempt, setAttempt] = useState(null); const [codingSession, setCodingSession] = useState(null); const [errorAction, setErrorAction] = useState('');
  const start = async (round) => { setErrorAction(''); try { const response = await api.post(`/student/rounds/${round._id}/start`); const session = dataOf(response); if (session.codingRoundId) setCodingSession(session); else setAttempt(session); } catch (reason) { setErrorAction(errorMessage(reason)); reload(); } };
  return <PageFrame><SectionHeading eyebrow="YOUR RECRUITMENT JOURNEY" title="Recruitment" description="See scheduled stages and outcomes from the companies you have chosen to engage with." />{error && <ErrorNotice message={error} onRetry={reload} />}{errorAction && <ErrorNotice message={errorAction} />}{loading ? <Loading /> : data?.rounds?.length ? <div className="student-round-list">{data.rounds.map((round) => { const result = data.results?.find((item) => String(item.round?._id || item.round) === String(round._id)); return <article className="student-round-card" key={round._id}><div className="round-number round-number-large">{String(round.roundNumber).padStart(2, '0')}</div><div className="student-round-main"><div className="round-topline"><Badge tone="blue">{round.company?.companyName}</Badge><Badge tone={statusTone(result?.result || round.status)}>{statusLabel(result?.result || round.status)}</Badge></div><h3>{round.name}</h3><p>{round.opportunity?.title} · {statusLabel(round.type)} · {round.date || 'Date to be confirmed'} {round.time ? `· ${round.time}` : ''}</p>{round.instructions && <div className="round-instructions">{round.instructions}</div>}{round.meetingLink && <a className="text-link" href={round.meetingLink} target="_blank" rel="noreferrer">Open meeting link<ArrowUpRight size={14} /></a>}{result && <div className="round-feedback"><strong>Outcome: {statusLabel(result.result)}{result.score !== undefined ? ` · ${result.score}%` : ''}</strong>{result.feedback && <p>{result.feedback}</p>}</div>}</div>{!result && (round.status === 'scheduled' || (round.type === 'coding' && round.status === 'in-progress')) && ['mcq', 'coding', 'custom-assessment'].includes(round.type) && <button className="button button-primary button-small" onClick={() => start(round)}>{round.type === 'coding' ? round.status === 'in-progress' ? 'Resume coding challenge' : 'Start coding challenge' : 'Start assessment'}<ArrowRight size={14} /></button>}</article>; })}</div> : <div className="panel"><EmptyState icon={ClipboardCheck} title="No rounds scheduled yet" description="When you accept an opportunity, its recruitment stages will appear here." action={{ label: 'View opportunities', onClick: () => window.location.assign('/student/opportunities') }} /></div>}{attempt && <Suspense fallback={<Loading label="Opening assessment?" />}><AssessmentRunner attempt={attempt} onClose={() => { setAttempt(null); reload(); }} /></Suspense>}{codingSession && <Suspense fallback={<Loading label="Opening coding challenge?" />}><CodingRoundRunner session={codingSession} onClose={() => { setCodingSession(null); reload(); }} /></Suspense>}</PageFrame>;
}

function AssessmentResults() {
  const { data, loading, error, reload } = useApiData('/student/assessments/attempts');
  return <PageFrame className="student-results-page"><SectionHeading eyebrow="LEARNING EVIDENCE" title="Assessment results" description="Review scores, strong topics and areas to revisit. Retake a set when you are ready." action={<Link className="button button-soft" to="/student/skills">Browse skills<Layers3 size={15} /></Link>} />{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : data?.length ? <div className="results-list">{data.filter((item) => item.status === 'submitted').map((attempt) => <article className="result-card" key={attempt._id}><div className="result-score"><strong>{attempt.percentage}<small>%</small></strong><span>{attempt.correct} of {attempt.totalQuestions} correct</span></div><div className="result-detail"><div className="result-head"><div><h3>{attempt.skill?.name || 'Skill assessment'}</h3><p>{attempt.difficulty} · Set {attempt.setNumber} · {new Date(attempt.submittedAt || attempt.createdAt).toLocaleDateString()}</p></div><Badge tone={attempt.percentage >= 70 ? 'green' : 'amber'}>{attempt.percentage >= 70 ? 'Strong result' : 'Keep practicing'}</Badge></div><ProgressBar value={attempt.percentage} tone={attempt.percentage >= 70 ? 'mint' : 'amber'} /><div className="result-breakdown"><div className="result-stat result-stat-correct"><CheckCircle2 size={17} /><span><strong>{attempt.correct}</strong><small>Correct</small></span></div><div className="result-stat result-stat-wrong"><X size={17} /><span><strong>{attempt.wrong}</strong><small>Wrong</small></span></div><div className="result-stat result-stat-skipped"><ArrowDownRight size={17} /><span><strong>{attempt.skipped}</strong><small>Skipped</small></span></div><div className="result-stat result-stat-time"><Clock3 size={17} /><span><strong>{Math.round((attempt.timeTakenSec || 0) / 60)} min</strong><small>Time taken</small></span></div></div>{attempt.weakTopics?.length > 0 && <div className="weak-topics"><span>Review next:</span>{attempt.weakTopics.map((topic) => <Badge tone="rose" key={topic}>{topic}</Badge>)}</div>}</div></article>)}</div> : <EmptyState icon={Award} title="Your first result is one test away" description="Complete a skill assessment and your history will appear here." action={{ label: 'Explore skill assessments', onClick: () => window.location.assign('/student/skills') }} />}</PageFrame>;
}

function NotificationInbox() {
  const { data, loading, error, reload } = useApiData('/notifications?limit=100'); const [busy, setBusy] = useState(false);
  const markRead = async (notification) => { if (notification.read) return; try { await api.patch(`/notifications/${notification._id}/read`); await reload(); } catch { /* Keep the inbox readable if an item was removed. */ } };
  const markAll = async () => { setBusy(true); try { await api.patch('/notifications/read-all'); await reload(); } finally { setBusy(false); } };
  return <PageFrame className="student-inbox-page"><SectionHeading eyebrow="IN-PORTAL MESSAGES" title="Your inbox" description="Approval updates, opportunity responses and admin messages live here. YESGAP does not send account or hiring messages by email." action={<button className="button button-soft" disabled={!data?.length || busy} onClick={markAll}>Mark all read<Check size={15} /></button>} />{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : data?.length ? <div className="inbox-list">{data.map((item) => <article className={`inbox-item ${item.read ? 'is-read' : 'is-unread'}`} key={item._id} onClick={() => markRead(item)}><div className={`inbox-icon inbox-${item.priority || 'normal'}`}><Bell size={17} /></div><div className="inbox-body"><div className="inbox-meta"><span>{statusLabel(item.type)}</span><time>{new Date(item.createdAt).toLocaleString()}</time></div><h3>{item.title}</h3><p>{item.body}</p>{item.link && <Link to={item.link.startsWith('/') ? item.link : `/${item.link}`} className="text-link" onClick={() => markRead(item)}>Open related page<ArrowRight size={14} /></Link>}</div>{!item.read && <i className="unread-dot" />}</article>)}</div> : <EmptyState icon={Bell} title="Your inbox is all caught up" description="YESGAP messages will appear here when there is something to review." />}</PageFrame>;
}

function Complaints({ role }) {
  const endpoint = role === 'admin' ? '/admin/complaints' : '/complaints';
  const { data, loading, error, reload } = useApiData(endpoint); const [createOpen, setCreateOpen] = useState(false); const [filter, setFilter] = useState('all'); const [busy, setBusy] = useState(''); const [message, setMessage] = useState('');
  const visible = (data || []).filter((row) => filter === 'all' || row.status === filter);
  const update = async (row, status) => { setBusy(row._id); setMessage(''); try { await api.patch(`/admin/complaints/${row._id}`, { status, note: status === 'in-review' ? 'An administrator is reviewing this request.' : status === 'resolved' ? 'This complaint has been resolved.' : undefined }); await reload(); setMessage('Complaint status updated and the submitter was notified.'); } catch (reason) { setMessage(errorMessage(reason)); } finally { setBusy(''); } };
  const submit = async (values) => { await api.post('/complaints', values); setCreateOpen(false); await reload(); };
  return <PageFrame className="complaints-page"><SectionHeading eyebrow={role === 'admin' ? 'PLATFORM SUPPORT' : 'DIRECT TO ADMIN'} title={role === 'admin' ? 'Complaints' : 'Help & feedback'} description={role === 'admin' ? 'Review reports from students and hiring companies, update their status and keep the sender informed.' : 'Send a private message directly to the YESGAP admin team and track its status here.'} action={role !== 'admin' && <button className="button button-primary" onClick={() => setCreateOpen(true)}><Plus size={15} />Submit a complaint</button>} />{message && <div className="notice success-notice"><CheckCircle2 size={16} />{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}{role === 'admin' && <div className="status-filter-row">{['all', 'open', 'in-review', 'resolved'].map((item) => <button key={item} className={`filter-pill ${filter === item ? 'active' : ''}`} onClick={() => setFilter(item)}>{item === 'all' ? 'All complaints' : statusLabel(item)}</button>)}</div>}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : visible.length ? <div className="complaint-list">{visible.map((row) => <article className="complaint-card" key={row._id}><div className="complaint-header"><div className="complaint-icon"><MessageSquareWarning size={17} /></div><div><h3>{row.subject}</h3><p>{row.user?.fullName || 'You'} · {statusLabel(row.role)} · {new Date(row.createdAt).toLocaleDateString()}</p></div><Badge tone={statusTone(row.status)}>{statusLabel(row.status)}</Badge></div><p className="complaint-message">{row.message}</p>{role === 'admin' && <div className="complaint-admin-footer"><span>{statusLabel(row.category)}</span><div>{row.status === 'open' && <button className="button button-soft button-small" disabled={busy === row._id} onClick={() => update(row, 'in-review')}>Start review</button>}{row.status !== 'resolved' && <button className="button button-primary button-small" disabled={busy === row._id} onClick={() => update(row, 'resolved')}>Resolve<Check size={14} /></button>}{row.status === 'resolved' && <span className="resolved-note">Resolved {row.resolvedAt ? new Date(row.resolvedAt).toLocaleDateString() : ''}</span>}</div></div>}{row.notes?.map((note, index) => <div className="complaint-note" key={index}><span>Admin update · {new Date(note.at).toLocaleDateString()}</span><p>{note.note}</p></div>)}</article>)}</div> : <EmptyState icon={MessageSquareWarning} title={role === 'admin' ? 'No complaints need attention' : 'No support messages yet'} description={role === 'admin' ? 'New student and company reports will appear in this queue.' : 'Your messages to the admin team and their current status will appear here.'} action={role !== 'admin' ? { label: 'Submit a complaint', onClick: () => setCreateOpen(true) } : undefined} />}{createOpen && <ComplaintModal onClose={() => setCreateOpen(false)} onSubmit={submit} />}</PageFrame>;
}

function ComplaintModal({ onClose, onSubmit }) {
  const [values, setValues] = useState({ category: 'other', subject: '', message: '' }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value }));
  const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await onSubmit(values); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  return <Modal title="Send a message to the admin team" onClose={onClose}><form className="modal-form" onSubmit={save}><Field label="Category"><FormSelect name="category" value={values.category} onChange={update}><option value="technical">Technical issue</option><option value="content">Learning content</option><option value="account">Account</option><option value="recruitment">Recruitment</option><option value="assessment">Assessment</option><option value="other">Other</option></FormSelect></Field><Field label="Subject"><FormInput required minLength="3" name="subject" value={values.subject} onChange={update} placeholder="What do you need help with?" /></Field><Field label="Message"><textarea required minLength="10" maxLength="8000" className="input textarea" rows="5" name="message" value={values.message} onChange={update} placeholder="Share enough detail for the admin team to help." /></Field>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button disabled={busy} className="button button-primary">{busy ? 'Sending…' : 'Send to admin'}<ArrowRight size={15} /></button></div></form></Modal>;
}

function AdminApprovals() {
  const [filter, setFilter] = useState('pending'); const [message, setMessage] = useState(''); const [busy, setBusy] = useState('');
  const { data, loading, error, reload } = useApiData(`/admin/companies?status=${filter}`);
  const review = async (company, status) => { setBusy(company._id); setMessage(''); try { await api.patch(`/admin/companies/${company._id}/approval`, { status, note: status === 'rejected' ? 'Please review the registration details and contact YESGAP support if you need help.' : 'Company profile reviewed and approved.' }); await reload(); setMessage(`Company ${status}. An in-portal notification was sent.`); } catch (reason) { setMessage(errorMessage(reason)); } finally { setBusy(''); } };
  return <PageFrame><SectionHeading eyebrow="COMPANY GOVERNANCE" title="Company approvals" description="Review company registrations before they get candidate discovery, opportunities and recruitment access." /><div className="status-filter-row">{['pending', 'approved', 'rejected'].map((status) => <button key={status} className={`filter-pill ${filter === status ? 'active' : ''}`} onClick={() => setFilter(status)}>{statusLabel(status)}</button>)}</div>{message && <div className="notice success-notice"><ShieldCheck size={16} />{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : data?.length ? <div className="approval-list">{data.map((company) => <article className="approval-card" key={company._id}><div className="company-avatar company-avatar-large">{initials(company.companyName)}</div><div className="approval-main"><div className="approval-title-row"><h3>{company.companyName}</h3><Badge tone={statusTone(company.approvalStatus)}>{statusLabel(company.approvalStatus)}</Badge></div><p>{company.industry || 'Technology'} · {company.location || 'Location not provided'}</p><div className="approval-contact"><span>{company.fullName}</span><span>{company.designation || 'Company member'}</span><span>{company.email}</span><span>{company.phone}</span></div><p className="approval-description">{company.description}</p><div className="skill-tag-row">{company.requiredSkills?.map((skill) => <span className="skill-tag" key={skill._id}>{skill.name}</span>)}</div><small>Registered {new Date(company.createdAt).toLocaleDateString()} · Expected hires: {company.expectedHires ?? 'Not specified'}</small></div>{company.approvalStatus === 'pending' && <div className="approval-actions"><button className="button button-primary button-small" disabled={busy === company._id} onClick={() => review(company, 'approved')}><Check size={14} />Approve</button><button className="button button-quiet button-small" disabled={busy === company._id} onClick={() => review(company, 'rejected')}>Reject</button></div>}</article>)}</div> : <EmptyState icon={ShieldCheck} title={`No ${filter} registrations`} description={filter === 'pending' ? 'New company registrations will appear in this queue.' : `There are no ${filter} company accounts right now.`} />}</PageFrame>;
}

function AdminUsers() {
  const [role, setRole] = useState('all'); const [query, setQuery] = useState(''); const [refresh, setRefresh] = useState(0); const [message, setMessage] = useState('');
  const params = new URLSearchParams(); if (role !== 'all') params.set('role', role); if (query) params.set('q', query);
  const { data, loading, error, reload } = useApiData(`/admin/users?${params.toString()}&refresh=${refresh}`);
  const setActive = async (user) => { try { await api.patch(`/admin/users/${user._id}/status`, { isActive: !user.isActive }); await reload(); setMessage(`${user.fullName} account ${user.isActive ? 'deactivated' : 'activated'}.`); } catch (reason) { setMessage(errorMessage(reason)); } };
  return <PageFrame><SectionHeading eyebrow="ACCOUNT MANAGEMENT" title="User accounts" description="Review role, profile and company approval status. Deactivation preserves account history." /><div className="candidate-filter-grid"><label className="search-field"><Search size={17} /><input placeholder="Search names or emails" value={query} onChange={(event) => setQuery(event.target.value)} /></label><select className="filter-select" value={role} onChange={(event) => setRole(event.target.value)}><option value="all">All roles</option><option value="student">Students</option><option value="company">Companies</option><option value="admin">Administrators</option></select></div>{message && <div className="notice success-notice">{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : data?.length ? <div className="admin-user-list">{data.map((account) => <article key={account._id} className="admin-user-row"><div className={`role-avatar role-${account.role}`}>{initials(account.fullName || account.companyName)}</div><div className="admin-user-main"><strong>{account.companyName || account.fullName}</strong><small>{account.username} · {account.email}</small></div><Badge tone={account.role === 'admin' ? 'violet' : account.role === 'company' ? 'blue' : 'neutral'}>{account.role}</Badge>{account.role === 'company' && <Badge tone={statusTone(account.approvalStatus)}>{statusLabel(account.approvalStatus)}</Badge>}<Badge tone={account.isActive ? 'green' : 'rose'}>{account.isActive ? 'Active' : 'Disabled'}</Badge>{!account.isSuperAdmin && <button className="text-button" onClick={() => setActive(account)}>{account.isActive ? 'Deactivate' : 'Reactivate'}</button>}</article>)}</div> : <EmptyState icon={UsersRound} title="No accounts found" description="Try changing the search or role filter." />}</PageFrame>;
}

function AdminDomains() {
  const { data, loading, error, reload } = useApiData('/admin/domains'); const [edit, setEdit] = useState(null); const [createOpen, setCreateOpen] = useState(false); const [notice, setNotice] = useState(''); const { data: skills } = useApiData('/admin/skills');
  const archive = async (domain) => { if (!window.confirm(`Archive ${domain.name}? It will no longer be available for new profile selection.`)) return; try { await api.delete(`/admin/domains/${domain._id}`); await reload(); } catch (reason) { setNotice(errorMessage(reason)); } };
  const saveSkills = async (domain, selected) => { await api.put(`/admin/domains/${domain._id}/skills`, { skills: selected.map((row, order) => ({ ...row, required: true, order })) }); await reload(); };
  return <PageFrame><SectionHeading eyebrow="DYNAMIC CAREER CATALOG" title="Career domains" description="Each domain links to the central skill catalog. These same links power student skill gaps and roadmaps." action={<button className="button button-primary" onClick={() => setCreateOpen(true)}><Plus size={15} />Add domain</button>} />{notice && <ErrorNotice message={notice} />}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : <div className="domain-admin-grid">{data?.map((domain) => <article className="domain-admin-card" key={domain._id}><div className="domain-admin-top"><span className="domain-accent" style={{ background: domain.accent || 'var(--accent)' }}><Layers3 size={18} /></span><Badge tone={domain.isActive ? 'green' : 'rose'}>{domain.isActive ? 'Active' : 'Archived'}</Badge></div><h3>{domain.name}</h3><p>{domain.description}</p><div className="domain-admin-count"><strong>{domain.skillLinks?.filter((link) => link.required).length || 0}</strong><span>required skills</span></div><div className="skill-tag-row">{domain.skillLinks?.slice(0, 6).map((link) => <span key={link._id} className="skill-tag">{link.skill?.name}</span>)}</div><div className="domain-card-actions"><button className="button button-soft button-small" onClick={() => setEdit(domain)}>Manage skills<ArrowRight size={14} /></button><button className="text-button" onClick={() => archive(domain)}>Archive</button></div></article>)}</div>}{edit && <DomainSkillsModal domain={edit} skills={skills || []} onClose={() => setEdit(null)} onSave={async (selected) => { await saveSkills(edit, selected); setEdit(null); }} />}{createOpen && <DomainModal onClose={() => setCreateOpen(false)} onSave={async (values) => { await api.post('/admin/domains', values); setCreateOpen(false); await reload(); }} />}</PageFrame>;
}

function DomainSkillsModal({ domain, skills, onClose, onSave }) {
  const [selected, setSelected] = useState(() => (domain.skillLinks || []).filter((link) => link.required).map((link) => ({
    skill: String(link.skill?._id || link.skill),
    weight: link.weight ?? 1,
    importanceWeight: link.importanceWeight ?? 3,
    importanceLevel: link.importanceLevel || ((link.importanceWeight ?? 3) >= 4 ? 'core' : 'supporting'),
  })));
  const [busy, setBusy] = useState(false); const [query, setQuery] = useState('');
  const toggle = (skill) => setSelected((current) => current.some((row) => row.skill === skill._id)
    ? current.filter((row) => row.skill !== skill._id)
    : [...current, { skill: skill._id, weight: 1, importanceWeight: 3, importanceLevel: 'supporting' }]);
  const update = (skillId, key, value) => setSelected((current) => current.map((row) => row.skill === skillId ? { ...row, [key]: value } : row));
  const save = async () => { setBusy(true); try { await onSave(selected); } finally { setBusy(false); } };
  return <Modal title={`Required skills · ${domain.name}`} onClose={onClose}><div className="modal-form">
    <p className="muted-note">Set each skill's importance for this domain. This is separate from the existing skill-gap weighting.</p>
    <label className="search-field"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Find a catalog skill" /></label>
    <div className="admin-skill-picker readiness-skill-picker">{skills.filter((skill) => matchesSearch(query, skill.name, skill.category, skill.tags)).map((skill) => {
      const row = selected.find((item) => item.skill === skill._id);
      return <div className="readiness-picker-option" key={skill._id}>
        <label className="picker-option"><input type="checkbox" checked={Boolean(row)} onChange={() => toggle(skill)} /><span><strong>{skill.name}</strong><small>{skill.category} · {skill.difficulty}</small></span></label>
        {row && <div className="readiness-picker-controls">
          <label>Role<select className="filter-select" value={row.importanceLevel} onChange={(event) => update(skill._id, 'importanceLevel', event.target.value)}><option value="core">Core</option><option value="supporting">Supporting</option></select></label>
          <label>Weight (1–5)<input className="input" type="number" min="1" max="5" step="0.5" value={row.importanceWeight} onChange={(event) => update(skill._id, 'importanceWeight', Number(event.target.value))} /></label>
        </div>}
      </div>;
    })}</div>
    <div className="modal-actions"><span className="subtle-label">{selected.length} required skills</span><button className="button button-primary" disabled={busy} onClick={save}>{busy ? 'Saving…' : 'Save skill links'}<Check size={15} /></button></div>
  </div></Modal>;
}

function AdminReadinessSettings() {
  const { data, loading, error, reload } = useApiData('/admin/readiness-settings');
  const [values, setValues] = useState(null); const [busy, setBusy] = useState(false); const [notice, setNotice] = useState(''); const [saveError, setSaveError] = useState('');
  useEffect(() => {
    if (!data) return;
    setValues({ confidence: { ...data.confidence }, freshness: { ...data.freshness }, verificationPassPercentage: data.verificationPassPercentage, marketDemand: { ...data.marketDemand } });
  }, [data]);
  const update = (section, key, value) => setValues((current) => ({
    ...current,
    [section]: typeof current[section] === 'object' ? { ...current[section], [key]: Number(value) } : Number(value),
  }));
  const save = async (event) => {
    event.preventDefault(); setBusy(true); setSaveError(''); setNotice('');
    try { const response = await api.put('/admin/readiness-settings', values); setValues(dataOf(response)); setNotice('Readiness settings saved. Relative platform demand was recalculated.'); await reload(); }
    catch (reason) { setSaveError(errorMessage(reason)); }
    finally { setBusy(false); }
  };
  if (loading) return <PageFrame><Loading /></PageFrame>;
  return <PageFrame><SectionHeading eyebrow="EXPLAINABLE SCORING" title="Career readiness model" description="Configure confidence, freshness, verification, and relative platform-demand factors used in student career readiness." />
    {error && <ErrorNotice message={error} onRetry={reload} />}{notice && <div className="notice success-notice"><CheckCircle2 size={16} />{notice}</div>}{saveError && <ErrorNotice message={saveError} />}
    {values && <form className="readiness-settings-form" onSubmit={save}>
      <section className="panel readiness-settings-panel"><SectionHeading eyebrow="FACTOR 1 · STATE CONFIDENCE" title="Confidence multipliers" description="Each multiplier must increase as evidence strengthens." /><div className="form-grid four-settings">{[['missing', 'Missing'], ['inProgress', 'In progress'], ['completed', 'Completed'], ['verified', 'Verified']].map(([key, label]) => <Field key={key} label={label}><FormInput type="number" min="0" max="1" step="0.05" value={values.confidence[key]} onChange={(event) => update('confidence', key, event.target.value)} /></Field>)}</div></section>
      <section className="panel readiness-settings-panel"><SectionHeading eyebrow="FACTOR 2 · FRESHNESS" title="Engagement decay" description="Revisiting learning, practice, or assessment resets the user's inactivity timer." /><div className="form-grid three-settings"><Field label="Grace period (days)"><FormInput type="number" min="0" max="3650" step="1" value={values.freshness.graceDays} onChange={(event) => update('freshness', 'graceDays', event.target.value)} /></Field><Field label="Decay duration (days)"><FormInput type="number" min="1" max="3650" step="1" value={values.freshness.decayDurationDays} onChange={(event) => update('freshness', 'decayDurationDays', event.target.value)} /></Field><Field label="Freshness floor (0–1)"><FormInput type="number" min="0" max="1" step="0.05" value={values.freshness.decayFloor} onChange={(event) => update('freshness', 'decayFloor', event.target.value)} /></Field></div></section>
      <section className="panel readiness-settings-panel"><SectionHeading eyebrow="FACTOR 3 / VERIFICATION" title="Assessment verification" description="Set the minimum assessment score required to verify a demonstrated skill." /><div className="form-grid readiness-verification-grid"><Field label="Assessment pass threshold (%)"><FormInput type="number" min="0" max="100" step="1" value={values.verificationPassPercentage} onChange={(event) => update('verificationPassPercentage', null, event.target.value)} /></Field></div></section>
      <section className="panel readiness-settings-panel"><SectionHeading eyebrow="FACTOR 4 / PLATFORM DEMAND" title="Opportunity demand bounds" description="Demand is recalculated daily from open opportunities posted by active, approved companies." /><div className="form-grid readiness-demand-grid"><Field label="Minimum multiplier"><FormInput type="number" min="0.5" max="1" step="0.05" value={values.marketDemand.minMultiplier} onChange={(event) => update('marketDemand', 'minMultiplier', event.target.value)} /></Field><Field label="Maximum multiplier"><FormInput type="number" min="1" max="2" step="0.05" value={values.marketDemand.maxMultiplier} onChange={(event) => update('marketDemand', 'maxMultiplier', event.target.value)} /></Field></div><p className="muted-note">Latest platform-opportunity refresh: {data?.marketDemand?.computedAt ? new Date(data.marketDemand.computedAt).toLocaleString() : 'No refresh recorded yet.'}</p></section>
      <div className="profile-save-row"><button className="button button-primary" disabled={busy}>{busy ? 'Saving…' : 'Save readiness settings'}<Check size={15} /></button></div>
    </form>}
  </PageFrame>;
}
function DomainModal({ onClose, onSave }) {
  const [values, setValues] = useState({ name: '', slug: '', description: '', category: 'programming', accent: '#39b6a5' }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value, ...(event.target.name === 'name' && !current.slug ? { slug: event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-') } : {}) }));
  const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await onSave(values); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  return <Modal title="Add a career domain" onClose={onClose}><form className="modal-form" onSubmit={save}><Field label="Domain name"><FormInput required name="name" value={values.name} onChange={update} /></Field><Field label="Slug"><FormInput required name="slug" value={values.slug} onChange={update} /></Field><Field label="Description"><textarea className="input textarea" rows="3" name="description" value={values.description} onChange={update} /></Field><Field label="Category"><FormSelect name="category" value={values.category} onChange={update}>{['programming', 'frontend', 'backend', 'fullstack', 'mobile', 'data', 'ai', 'cloud', 'devops', 'security', 'database', 'quality', 'design', 'infrastructure', 'emerging'].map((value) => <option key={value}>{value}</option>)}</FormSelect></Field>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>Create domain<ArrowRight size={14} /></button></div></form></Modal>;
}

function AdminSkills() {
  const { data, loading, error, reload } = useApiData('/admin/skills'); const [open, setOpen] = useState(false); const [query, setQuery] = useState(''); const [notice, setNotice] = useState('');
  const filtered = (data || []).filter((skill) => matchesSearch(query, skill.name, skill.category, skill.tags, skill.shortDescription));
  const archive = async (skill) => { try { await api.delete(`/admin/skills/${skill._id}`); await reload(); } catch (reason) { setNotice(errorMessage(reason)); } };
  return <PageFrame><SectionHeading eyebrow="SINGLE SOURCE OF TRUTH" title="Skills catalog" description="Skills are shared by gap analysis, learning, assessments, company requirements and candidate profiles." action={<button className="button button-primary" onClick={() => setOpen(true)}><Plus size={15} />Add skill</button>} /><label className="search-field admin-search"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search the catalog" /></label>{notice && <ErrorNotice message={notice} />}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : <div className="admin-skill-list">{filtered.map((skill) => <article className="admin-skill-row" key={skill._id}><span className="skill-monogram">{skill.name.slice(0, 2).toUpperCase()}</span><div className="admin-skill-main"><strong>{skill.name}</strong><small>{skill.category} · {skill.difficulty} · {skill.executionType}</small></div><Badge tone={skill.isActive ? 'green' : 'rose'}>{skill.isActive ? 'Active' : 'Archived'}</Badge><span className="skill-lang-list">{skill.supportedLanguages?.join(', ')}</span>{skill.isActive && <button className="text-button" onClick={() => archive(skill)}>Archive</button>}</article>)}</div>}{open && <SkillModal onClose={() => setOpen(false)} onSave={async (values) => { await api.post('/admin/skills', values); setOpen(false); await reload(); }} />}</PageFrame>;
}

function SkillModal({ onClose, onSave }) {
  const [values, setValues] = useState({ name: '', slug: '', category: 'programming language', difficulty: 'beginner', executionType: 'none', shortDescription: '', description: '', supportedLanguages: [] }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value, ...(event.target.name === 'name' && !current.slug ? { slug: event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-') } : {}) }));
  const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await onSave(values); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  return <Modal title="Add a catalog skill" onClose={onClose}><form className="modal-form" onSubmit={save}><Field label="Skill name"><FormInput required name="name" value={values.name} onChange={update} /></Field><Field label="URL slug"><FormInput required name="slug" value={values.slug} onChange={update} /></Field><div className="form-grid"><Field label="Category"><FormInput required name="category" value={values.category} onChange={update} /></Field><Field label="Difficulty"><FormSelect name="difficulty" value={values.difficulty} onChange={update}><option>beginner</option><option>intermediate</option><option>advanced</option></FormSelect></Field></div><Field label="Execution surface"><FormSelect name="executionType" value={values.executionType} onChange={update}>{['none', 'html-preview', 'css-preview', 'js-runtime', 'python-runtime', 'java-runtime', 'c-compiler', 'cpp-compiler', 'node-runtime', 'react-preview', 'sql-sandbox'].map((value) => <option key={value}>{value}</option>)}</FormSelect></Field><Field label="Short description"><FormInput name="shortDescription" value={values.shortDescription} onChange={update} /></Field><Field label="About this skill"><textarea required className="input textarea" rows="3" name="description" value={values.description} onChange={update} /></Field>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>{busy ? 'Saving…' : 'Add skill'}<ArrowRight size={14} /></button></div></form></Modal>;
}

function AdminLearning() {
  const { data, loading, error, reload } = useApiData('/admin/learning'); const { data: skills } = useApiData('/admin/skills'); const [open, setOpen] = useState(false); const [query, setQuery] = useState(''); const [message, setMessage] = useState('');
  const filtered = (data || []).filter((module) => matchesSearch(query, module.title, module.description, module.skill?.name, module.topics, module.objectives));
  const unpublish = async (module) => { try { await api.delete(`/admin/learning/${module._id}`); await reload(); } catch (reason) { setMessage(errorMessage(reason)); } };
  return <PageFrame><SectionHeading eyebrow="DATABASE-DRIVEN CURRICULUM" title="Learning content" description="Create and manage published modules stored in MongoDB. Each module belongs to one central catalog skill." action={<button className="button button-primary" onClick={() => setOpen(true)}><Plus size={15} />Add module</button>} /><label className="search-field admin-search"><Search size={17} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search lessons or skills" /></label>{message && <ErrorNotice message={message} />}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : filtered.length ? <div className="learning-admin-list">{filtered.map((module) => <article className="admin-module-row" key={module._id}><div className="module-index">{String(module.order).padStart(2, '0')}</div><div className="admin-module-main"><strong>{module.title}</strong><small>{module.skill?.name} · {module.level} · {module.subtopicCount || module.topics?.reduce((sum, topic) => sum + (topic.subtopics?.length || 0), 0)} subtopics</small><p>{module.description}</p></div><Badge tone={module.isPublished ? 'green' : 'rose'}>{module.isPublished ? 'Published' : 'Draft'}</Badge><button className="text-button" onClick={() => unpublish(module)}>Unpublish</button></article>)}</div> : <EmptyState icon={BookOpen} title="No learning modules yet" description="Create the first module attached to a skill in the shared catalog." />}{open && <ModuleModal skills={skills || []} onClose={() => setOpen(false)} onSave={async (values) => { await api.post('/admin/learning', values); setOpen(false); await reload(); }} />}</PageFrame>;
}

function ModuleModal({ skills, onClose, onSave }) {
  const [values, setValues] = useState({ skill: '', title: '', slug: '', level: 'beginner', description: '', order: 1, topicsJson: '[\n  {\n    "title": "Introduction",\n    "order": 1,\n    "overview": "Introduce the key concepts.",\n    "subtopics": [\n      { "title": "Core concept", "theory": "Write the lesson content here.", "examples": [], "checkpoints": [] }\n    ]\n  }\n]' }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value, ...(event.target.name === 'title' && !current.slug ? { slug: event.target.value.toLowerCase().replace(/[^a-z0-9]+/g, '-') } : {}) }));
  const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { const topics = JSON.parse(values.topicsJson); await onSave({ skill: values.skill, title: values.title, slug: values.slug, level: values.level, description: values.description, order: Number(values.order), topics }); } catch (reason) { setError(reason instanceof SyntaxError ? 'Topics must be valid JSON.' : errorMessage(reason)); } finally { setBusy(false); } };
  return <Modal title="Create a learning module" onClose={onClose}><form className="modal-form" onSubmit={save}><Field label="Catalog skill"><FormSelect required name="skill" value={values.skill} onChange={update}><option value="">Choose a skill</option>{skills.filter((skill) => skill.isActive).map((skill) => <option key={skill._id} value={skill._id}>{skill.name}</option>)}</FormSelect></Field><Field label="Module title"><FormInput required name="title" value={values.title} onChange={update} /></Field><div className="form-grid"><Field label="Slug"><FormInput required name="slug" value={values.slug} onChange={update} /></Field><Field label="Difficulty"><FormSelect name="level" value={values.level} onChange={update}><option>beginner</option><option>intermediate</option><option>advanced</option></FormSelect></Field></div><Field label="Description"><textarea className="input textarea" rows="2" name="description" value={values.description} onChange={update} /></Field><Field label="Topics and subtopics (JSON)" hint="Content is saved as structured topics, theory, examples and checkpoints."><textarea className="input textarea code-textarea" rows="12" name="topicsJson" value={values.topicsJson} onChange={update} /></Field>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>{busy ? 'Saving…' : 'Publish module'}<ArrowRight size={15} /></button></div></form></Modal>;
}

function AdminActivity() {
  const { user } = useAuth(); const { data, loading, error, reload } = useApiData('/admin/audit-logs'); const [showCreate, setShowCreate] = useState(false); const [message, setMessage] = useState('');
  const createAdmin = async (values) => { await api.post('/admin/admins', values); setShowCreate(false); setMessage('Administrator account created. The new admin must change their temporary password at sign-in.'); await reload(); };
  return <PageFrame><SectionHeading eyebrow="TRUST AND GOVERNANCE" title="Activity & audit" description="Privileged changes are recorded with an actor and target so important platform decisions are traceable." action={user.isSuperAdmin && <button className="button button-primary" onClick={() => setShowCreate(true)}><Plus size={15} />Provision admin</button>} />{message && <div className="notice success-notice"><ShieldCheck size={16} />{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}{loading ? <Loading /> : error ? <ErrorNotice message={error} onRetry={reload} /> : data?.length ? <div className="audit-list">{data.map((row) => <article className="audit-row audit-row-full" key={row._id}><div className="audit-dot"><ShieldCheck size={14} /></div><div><strong>{row.description || statusLabel(row.action)}</strong><small>{row.actor?.fullName || 'Administrator'} · {new Date(row.createdAt).toLocaleString()} · {row.targetType || 'Platform'}{row.targetId ? ` · ${String(row.targetId).slice(-6)}` : ''}</small></div><Badge tone="neutral">{auditLabel(row)}</Badge></article>)}</div> : <EmptyState icon={FileText} title="The audit trail is clear" description="Approvals, account provisioning and content changes will appear here." />}{showCreate && <AdminCreateModal onClose={() => setShowCreate(false)} onSave={createAdmin} />}</PageFrame>;
}

function AdminCreateModal({ onClose, onSave }) {
  const [values, setValues] = useState({ username: '', fullName: '', email: '', phone: '', temporaryPassword: '' }); const [busy, setBusy] = useState(false); const [error, setError] = useState('');
  const update = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value }));
  const save = async (event) => { event.preventDefault(); setBusy(true); setError(''); try { await onSave(values); } catch (reason) { setError(errorMessage(reason)); } finally { setBusy(false); } };
  return <Modal title="Provision an administrator" onClose={onClose}><form className="modal-form" onSubmit={save}><div className="notice"><ShieldCheck size={15} />Admin accounts are provisioned by the super admin. No request or approval flow is used.</div><Field label="Full name"><FormInput required name="fullName" value={values.fullName} onChange={update} /></Field><Field label="Username"><FormInput required name="username" value={values.username} onChange={update} /></Field><div className="form-grid"><Field label="Email"><FormInput required type="email" name="email" value={values.email} onChange={update} /></Field><Field label="Phone"><FormInput required name="phone" value={values.phone} onChange={update} /></Field></div><Field label="Temporary password" hint="At least 12 characters. Share through your company’s approved secure process."><FormInput required minLength="12" type="password" name="temporaryPassword" value={values.temporaryPassword} onChange={update} /></Field>{error && <div className="form-alert form-alert-error">{error}</div>}<div className="modal-actions"><button type="button" className="button button-quiet" onClick={onClose}>Cancel</button><button className="button button-primary" disabled={busy}>{busy ? 'Creating…' : 'Create administrator'}<ArrowRight size={15} /></button></div></form></Modal>;
}

function Profile({ user, onUserUpdated }) {
  const { data, loading, error, reload } = useApiData(user.role === 'student' ? '/student/profile' : null);
  const { data: domains } = useApiData(user.role === 'student' ? '/catalog/domains' : null);
  const { data: catalog } = useApiData(user.role === 'company' ? '/catalog/skills' : null);
  const [values, setValues] = useState({}); const [saving, setSaving] = useState(false); const [message, setMessage] = useState(''); const [errorMessageText, setErrorMessageText] = useState(''); const [resumeBusy, setResumeBusy] = useState(false); const [password, setPassword] = useState({ currentPassword: '', password: '', confirm: '' }); const [passwordMessage, setPasswordMessage] = useState(''); const [activeTab, setActiveTab] = useState('personal');
  useEffect(() => {
    const profileUser = data?.user || user;
    setValues({
      fullName: profileUser.fullName || '', email: profileUser.email || '', phone: profileUser.phone || '', theme: profileUser.theme || 'midnight', timezone: profileUser.timezone || 'Asia/Kolkata',
      headline: profileUser.headline || '', domainId: profileUser.careerDomain?._id || profileUser.careerDomain || '',
      college: profileUser.education?.undergraduate?.college || '', degree: profileUser.education?.undergraduate?.degree || '', specialization: profileUser.education?.undergraduate?.specialization || '', cgpa: profileUser.education?.undergraduate?.cgpa ?? '', startYear: profileUser.education?.undergraduate?.startYear || '', graduationYear: profileUser.education?.undergraduate?.graduationYear || '',
      companyName: profileUser.companyName || '', designation: profileUser.designation || '', industry: profileUser.industry || '', description: profileUser.description || '', website: profileUser.website || '', location: profileUser.location || '', companySize: profileUser.companySize || '', expectedCompensation: profileUser.expectedCompensation || '', expectedHires: profileUser.expectedHires || '', hiringRequirements: profileUser.hiringRequirements || '',
      requiredSkills: (profileUser.requiredSkills || []).map((item) => String(item?._id || item)),
    });
  }, [data, user]);
  const field = (event) => setValues((current) => ({ ...current, [event.target.name]: event.target.value }));
  const save = async (event) => {
    event.preventDefault(); setSaving(true); setMessage(''); setErrorMessageText('');
    const common = { fullName: values.fullName, email: values.email, phone: values.phone, theme: values.theme, timezone: values.timezone };
    const payload = user.role === 'student' ? {
      ...common,
      headline: values.headline, careerDomain: values.domainId || undefined,
      education: { ...data?.user?.education, undergraduate: { ...(data?.user?.education?.undergraduate || {}), college: values.college, degree: values.degree, specialization: values.specialization, cgpa: values.cgpa === '' ? undefined : Number(values.cgpa), startYear: values.startYear ? Number(values.startYear) : undefined, graduationYear: values.graduationYear ? Number(values.graduationYear) : undefined } },
    } : user.role === 'company' ? {
      ...common,
      companyName: values.companyName, designation: values.designation, industry: values.industry, description: values.description, website: values.website, location: values.location, companySize: values.companySize || undefined, expectedCompensation: values.expectedCompensation, expectedHires: values.expectedHires ? Number(values.expectedHires) : undefined, hiringRequirements: values.hiringRequirements, requiredSkills: values.requiredSkills || [],
    } : common;
    try { const response = await api.patch('/profile', payload); onUserUpdated(dataOf(response)); const refreshed = await api.get('/auth/me'); onUserUpdated(dataOf(refreshed)); setMessage('Your profile has been saved.'); await reload(); }
    catch (reason) { setErrorMessageText(errorMessage(reason)); }
    finally { setSaving(false); }
  };
  const setSkillStatus = async (skillId, status) => { setErrorMessageText(''); try { await api.put(`/student/skills/${skillId}`, { status }); await reload(); } catch (reason) { setErrorMessageText(errorMessage(reason)); } };
  const uploadResume = async (event) => {
    const file = event.target.files?.[0]; if (!file) return;
    setResumeBusy(true); setErrorMessageText('');
    try { const form = new FormData(); form.append('resume', file); await api.post('/student/resume', form, { headers: { 'Content-Type': 'multipart/form-data' } }); await reload(); setMessage('Resume uploaded securely to YESGAP.'); }
    catch (reason) { setErrorMessageText(errorMessage(reason)); }
    finally { setResumeBusy(false); event.target.value = ''; }
  };
  const changePassword = async (event) => {
    event.preventDefault(); setPasswordMessage(''); setErrorMessageText('');
    if (password.password !== password.confirm) { setErrorMessageText('Your new passwords do not match.'); return; }
    try { await api.patch('/auth/password', { currentPassword: password.currentPassword, password: password.password }); setPasswordMessage('Password updated. Other sessions have been signed out.'); setPassword({ currentPassword: '', password: '', confirm: '' }); }
    catch (reason) { setErrorMessageText(errorMessage(reason)); }
  };
  const toggleCompanySkill = (id) => setValues((current) => ({ ...current, requiredSkills: current.requiredSkills.includes(id) ? current.requiredSkills.filter((item) => item !== id) : [...current.requiredSkills, id] }));
  if (user.role === 'student' && loading) return <PageFrame><Loading /></PageFrame>;
  return <PageFrame className="account-profile-page"><SectionHeading eyebrow="YOUR YESGAP ACCOUNT" title={user.role === 'company' ? 'Company profile & settings' : user.role === 'admin' ? 'Administrator account' : 'Profile & settings'} description={user.role === 'student' ? 'Keep your contact, education and career direction current. Your progress comes from what you do in the platform.' : user.role === 'company' ? 'Help candidates understand your team, the roles you hire for and how you work.' : 'Manage your administrator contact details and access settings.'} />{error && <ErrorNotice message={error} onRetry={reload} />}{errorMessageText && <ErrorNotice message={errorMessageText} />}{message && <div className="notice success-notice"><CheckCircle2 size={16} />{message}<button onClick={() => setMessage('')}><X size={14} /></button></div>}<div className="profile-layout"><aside className="profile-side"><div className="profile-avatar-large">{initials(user.fullName || user.companyName)}</div><h3>{user.companyName || user.fullName}</h3><p>{user.role === 'company' ? user.industry || 'Company account' : user.role === 'admin' ? user.isSuperAdmin ? 'Super administrator' : 'YESGAP administrator' : data?.user?.careerDomain?.name || 'Student profile'}</p><div className="profile-side-menu">{['personal', ...(user.role === 'student' ? ['education', 'skills', 'resume'] : user.role === 'company' ? ['hiring'] : []), 'appearance', 'security'].map((tab) => <button className={activeTab === tab ? 'active' : ''} onClick={() => setActiveTab(tab)} key={tab}>{tab === 'personal' ? 'Personal details' : tab === 'education' ? 'Education' : tab === 'skills' ? 'Known skills' : tab === 'resume' ? 'Resume' : tab === 'hiring' ? 'Hiring profile' : tab === 'appearance' ? 'Appearance' : 'Security'}</button>)}</div></aside>
      <div className="profile-content"><div className="profile-form">
        {activeTab === 'personal' && <section className="panel profile-panel"><SectionHeading eyebrow="YOUR IDENTITY" title="Personal details" description="This information is visible in your own profile and account settings." /><div className="form-grid"><Field label="Full name"><FormInput required name="fullName" value={values.fullName || ''} onChange={field} /></Field><Field label="Username"><FormInput value={user.username || ''} disabled /></Field></div><div className="form-grid"><Field label="Email"><FormInput type="email" required name="email" value={values.email || ''} onChange={field} /></Field><Field label="Phone"><FormInput name="phone" required value={values.phone || ''} onChange={field} /></Field></div>{user.role === 'student' ? <><Field label="Profile headline"><FormInput name="headline" value={values.headline || ''} onChange={field} placeholder="What you are learning or building" /></Field><Field label="Career direction"><FormSelect name="domainId" value={values.domainId || ''} onChange={field}><option value="">Choose a domain</option>{(domains || []).map((domain) => <option key={domain._id} value={domain._id}>{domain.name}</option>)}</FormSelect><small>Changing this recalculates your required skills and roadmap.</small></Field></> : user.role === 'company' ? <><div className="form-grid"><Field label="Company name"><FormInput required name="companyName" value={values.companyName || ''} onChange={field} /></Field><Field label="Industry"><FormInput name="industry" value={values.industry || ''} onChange={field} /></Field></div><div className="form-grid"><Field label="Designation"><FormInput name="designation" value={values.designation || ''} onChange={field} /></Field><Field label="Website"><FormInput name="website" value={values.website || ''} onChange={field} /></Field></div><Field label="Location"><FormInput name="location" value={values.location || ''} onChange={field} /></Field><Field label="Company description"><textarea className="input textarea" rows="4" name="description" value={values.description || ''} onChange={field} /></Field></> : <div className="notice"><ShieldCheck size={16} />Administrator accounts are provisioned by the super admin. Public admin registration is disabled.</div>}<div className="profile-save-row"><button type="button" className="button button-primary" disabled={saving} onClick={save}>{saving ? 'Saving…' : 'Save profile'}<Check size={15} /></button></div></section>}
        {activeTab === 'education' && user.role === 'student' && <section className="panel profile-panel"><SectionHeading eyebrow="STUDENT PROFILE" title="Education" description="Education details can be updated at any time and are shared with a company only after you accept an opportunity." /><div className="form-grid"><Field label="Degree"><FormInput name="degree" value={values.degree || ''} onChange={field} placeholder="B.Tech" /></Field><Field label="Specialization"><FormInput name="specialization" value={values.specialization || ''} onChange={field} /></Field></div><Field label="College"><FormInput name="college" value={values.college || ''} onChange={field} /></Field><div className="form-grid"><Field label="CGPA (out of 10)"><FormInput type="number" min="0" max="10" step="0.01" name="cgpa" value={values.cgpa || ''} onChange={field} /></Field><Field label="College start year"><FormInput type="number" name="startYear" value={values.startYear || ''} onChange={field} /></Field><Field label="Graduation year"><FormInput type="number" name="graduationYear" value={values.graduationYear || ''} onChange={field} /></Field></div><div className="profile-save-row"><button type="button" className="button button-primary" disabled={saving} onClick={save}>Save education<Check size={15} /></button></div></section>}
        {activeTab === 'skills' && user.role === 'student' && <section className="panel profile-panel"><SectionHeading eyebrow="YOUR SKILL BASELINE" title="Known skills" description="Choose skills from the shared catalog. Learning progress and completed status are calculated from real activity." action={<Link className="small-link" to="/student/skills">All skills<ArrowRight size={14} /></Link>} /><div className="profile-skill-list">{(data?.skills || []).map((row) => <div className="profile-skill-row" key={row._id}><div className="profile-skill-copy"><strong>{row.skill?.name}</strong><small>{row.skill?.category || 'Skill'}</small><div className="profile-skill-progress"><div><span>Learning progress</span><strong>{row.progress || 0}%</strong></div><ProgressBar value={row.progress || 0} /></div></div><select className="profile-skill-status" aria-label={`Update ${row.skill?.name} status`} value={row.status === 'completed' ? 'completed' : row.status} disabled={row.status === 'completed'} onChange={(event) => setSkillStatus(row.skill._id, event.target.value)}><option value="known">Known</option><option value="in-progress">In progress</option><option value="missing">Remove</option>{row.status === 'completed' && <option value="completed">Completed</option>}</select></div>)}{!data?.skills?.length && <EmptyState icon={Layers3} title="No skills in your profile" description="Browse the catalog and add skills you already know." action={{ label: 'Browse skills', onClick: () => window.location.assign('/student/skills') }} />}</div></section>}
        {activeTab === 'resume' && user.role === 'student' && <section className="panel profile-panel"><SectionHeading eyebrow="OPTIONAL DOCUMENT" title="Your resume" description="Resume upload is optional. The file is stored inside MongoDB and companies cannot access it until you accept their opportunity." /><div className="resume-panel"><div className="resume-icon"><FileText size={22} /></div><div className="resume-copy">{data?.user?.resume?.fileId ? <><strong>{data.user.resume.fileName}</strong><small>{Math.round((data.user.resume.size || 0) / 1024)} KB · Uploaded {new Date(data.user.resume.uploadedAt).toLocaleDateString()}</small></> : <><strong>No resume uploaded</strong><small>Manual skills and profile details work without a resume.</small></>}</div>{data?.user?.resume?.fileId && <a className="text-link" href={`${import.meta.env.VITE_API_URL || '/api'}/resumes/${data.user.resume.fileId}`} target="_blank" rel="noreferrer">Download<ArrowUpRight size={14} /></a>}</div><label className="button button-soft upload-label">{resumeBusy ? 'Uploading…' : data?.user?.resume?.fileId ? 'Replace resume' : 'Upload resume'}<input type="file" accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" onChange={uploadResume} disabled={resumeBusy} /></label><small className="resume-limit">PDF or DOCX · up to 5 MB</small></section>}
        {activeTab === 'hiring' && user.role === 'company' && <section className="panel profile-panel"><SectionHeading eyebrow="HIRING PROFILE" title="What your team is looking for" description="Required skills stay connected to the same shared catalog used by student skill-gap analysis." /><div className="form-grid"><Field label="Company size"><FormSelect name="companySize" value={values.companySize || ''} onChange={field}><option value="">Choose range</option>{['1-10', '11-50', '51-200', '201-500', '501-1000', '1000+'].map((value) => <option key={value}>{value}</option>)}</FormSelect></Field><Field label="Expected compensation"><FormInput name="expectedCompensation" value={values.expectedCompensation || ''} onChange={field} /></Field></div><Field label="Expected hires"><FormInput type="number" min="0" name="expectedHires" value={values.expectedHires || ''} onChange={field} /></Field><Field label="Hiring requirements"><textarea className="input textarea" rows="4" name="hiringRequirements" value={values.hiringRequirements || ''} onChange={field} /></Field><Field label="Required skills"><div className="skill-select-grid">{(catalog || []).map((skill) => <button className={`skill-select-chip ${values.requiredSkills?.includes(skill._id) ? 'selected' : ''}`} type="button" key={skill._id} onClick={() => toggleCompanySkill(skill._id)}>{values.requiredSkills?.includes(skill._id) && <Check size={13} />}{skill.name}</button>)}</div></Field><div className="profile-save-row"><button type="button" className="button button-primary" disabled={saving} onClick={save}>Save hiring profile<Check size={15} /></button></div></section>}
        {activeTab === 'appearance' && <section className="panel profile-panel"><SectionHeading eyebrow="YOUR PREFERENCES" title="Appearance" description="See each palette before applying it. Your choice follows your account across devices and workspaces." /><div className="theme-choice-grid">{themeOptions.map((item) => <button type="button" className={"theme-choice theme-choice-" + item.value + (values.theme === item.value ? " selected" : "")} key={item.value} onClick={() => setValues((current) => ({ ...current, theme: item.value }))}><span className="theme-swatch" style={{ '--choice-bg': item.previewBg, '--choice-surface': item.previewSurface, '--choice-accent': item.color }}><i /><i /><i /></span><strong>{item.label}</strong><small>{item.description}</small>{values.theme === item.value && <CheckCircle2 size={16} />}</button>)}</div><div className="form-grid"><Field label="Learning timezone"><FormSelect name="timezone" value={values.timezone || 'Asia/Kolkata'} onChange={field}><option value="Asia/Kolkata">India Standard Time</option><option value="Asia/Singapore">Singapore Time</option><option value="Europe/London">United Kingdom</option><option value="America/New_York">US Eastern</option><option value="America/Los_Angeles">US Pacific</option><option value="UTC">UTC</option></FormSelect></Field></div><div className="profile-save-row"><button type="button" className="button button-primary" disabled={saving} onClick={save}>{saving ? 'Saving...' : 'Save appearance'}<Check size={15} /></button></div></section>}
        {activeTab === 'security' && <section className="panel profile-panel"><SectionHeading eyebrow="ACCOUNT SECURITY" title="Change password" description="Password recovery is handled by an administrator-issued temporary password in the in-portal inbox. There is no external reset email." /><form className="password-form" onSubmit={changePassword}><Field label="Current password"><FormInput required type="password" value={password.currentPassword} onChange={(event) => setPassword((current) => ({ ...current, currentPassword: event.target.value }))} autoComplete="current-password" /></Field><Field label="New password"><FormInput required minLength="10" type="password" value={password.password} onChange={(event) => setPassword((current) => ({ ...current, password: event.target.value }))} autoComplete="new-password" /></Field><Field label="Confirm new password"><FormInput required minLength="10" type="password" value={password.confirm} onChange={(event) => setPassword((current) => ({ ...current, confirm: event.target.value }))} autoComplete="new-password" /></Field>{passwordMessage && <div className="form-alert form-alert-success">{passwordMessage}</div>}<button className="button button-primary">Update password<LockKeyIconSmall /></button></form></section>}
      </div></div></div></PageFrame>;
}
function LockKeyIconSmall() { return <ShieldCheck size={15} />; }
